DROP TABLE IF EXISTS `content_media`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `content_media` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `content_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '内容编码',
  `media_type` tinyint NOT NULL COMMENT '媒体类型（1=图片, 2=视频, 3=音频, 4=附件）',
  `media_url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源URL',
  `thumbnail_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '缩略图URL',
  `media_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '资源名称',
  `file_format` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件格式',
  `file_size` int DEFAULT NULL COMMENT '文件大小（KB）',
  `width` int DEFAULT NULL COMMENT '宽度（像素）',
  `height` int DEFAULT NULL COMMENT '高度（像素）',
  `duration` int DEFAULT NULL COMMENT '时长（秒，视频/音频）',
  `media_description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '资源描述',
  `is_in_body` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否在正文中（0=否, 1=是）',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序号',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  KEY `idx_content_code` (`content_code`),
  KEY `idx_media_type` (`media_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='内容多媒体资源';
/*!40101 SET character_set_client = @saved_cs_client */;

