DROP TABLE IF EXISTS `course_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `course_info` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `course_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '课程编码',
  `course_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '课程名称',
  `course_type` tinyint NOT NULL COMMENT '课程类型（1=线上录播, 2=线上直播, 3=线下课程, 4=混合课程）',
  `category_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分类编码',
  `cover_image` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面图URL',
  `video_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '宣传视频URL',
  `course_description` text COLLATE utf8mb4_unicode_ci COMMENT '课程描述',
  `course_outline` text COLLATE utf8mb4_unicode_ci COMMENT '课程大纲（JSON格式）',
  `target_audience` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '目标人群',
  `learning_objectives` text COLLATE utf8mb4_unicode_ci COMMENT '学习目标',
  `lecturer_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主讲讲师编码',
  `total_class` int NOT NULL DEFAULT '0' COMMENT '总课时数',
  `total_duration` int DEFAULT NULL COMMENT '总时长（分钟）',
  `valid_days` int DEFAULT NULL COMMENT '有效天数',
  `original_price` decimal(12,2) NOT NULL COMMENT '原价',
  `sale_price` decimal(12,2) NOT NULL COMMENT '售价',
  `max_students` int DEFAULT NULL COMMENT '最大学员数（线下/直播课）',
  `current_students` int NOT NULL DEFAULT '0' COMMENT '当前学员数',
  `view_count` int NOT NULL DEFAULT '0' COMMENT '浏览次数',
  `sales_count` int NOT NULL DEFAULT '0' COMMENT '已售数量',
  `rating_avg` decimal(3,2) DEFAULT NULL COMMENT '平均评分',
  `is_free` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否免费（0=否, 1=是）',
  `is_recommend` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否推荐',
  `course_start_date` date DEFAULT NULL COMMENT '开课日期',
  `course_end_date` date DEFAULT NULL COMMENT '结课日期',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序号',
  `course_status` tinyint NOT NULL DEFAULT '0' COMMENT '状态（0=草稿, 1=待上架, 2=已上架, 3=已下架, 4=已结课）',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_course_code` (`course_code`),
