--
-- Table structure for table `equity_depot`
--

DROP TABLE IF EXISTS `equity_depot`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `equity_depot` (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `equity_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '权益编码（EQ+12位数字）',
  `equity_no` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '权益卡号（对外展示用）',
  `goods_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品编码（入库时从批次快照）',
  `person_count` int NOT NULL DEFAULT '1' COMMENT '使用人人数快照（入库时从 goods_equity 冻结）',
  `valid_days` int NOT NULL DEFAULT '365' COMMENT '激活后有效天数快照（入库时从 goods_equity 冻结）',
  `batch_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '批次编码',
  `cost_price` decimal(12,2) NOT NULL COMMENT '成本价',
  `channel_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分配渠道编码',
  `agent_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分配代理人编码',
  `client_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '领取客户编码',
  `produce_time` datetime NOT NULL COMMENT '入库时间',
  `allocate_time` datetime DEFAULT NULL COMMENT '分配时间',
  `outbound_channel_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '出库寄送渠道编码（出库时填写，记录寄送给哪个渠道）',
  `outbound_agent_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '出库寄送代理人编码（出库时填写，记录寄送给哪个代理人）',
  `outbound_time` datetime DEFAULT NULL COMMENT '出库时间',
  `logistics_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物流单号（出库寄送物流追踪号）',
  `activate_time` datetime DEFAULT NULL COMMENT '激活时间',
  `first_use_time` datetime DEFAULT NULL COMMENT '首次使用时间',
  `last_use_time` datetime DEFAULT NULL COMMENT '最近使用时间',
  `expire_time` datetime DEFAULT NULL COMMENT '过期时间（激活后计算）',
  `shelf_expire_time` datetime NOT NULL COMMENT '库存过期时间（未激活有效期）',
  `card_secret` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '卡密（加密存储，激活验证用）',
  `carrier_type` tinyint NOT NULL DEFAULT '1' COMMENT '载体类型（1=权益卡, 2=权益函）',
  `activate_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '激活码（DY-8位，权益卡专用）',
  `bind_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '绑定码（BF-12位，权益函专用）',
  `qr_code_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '权益二维码URL',
  `order_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联订单编码',
  `equity_status` tinyint NOT NULL DEFAULT '0' COMMENT '权益状态（0=库存中, 1=已出库, 2=已激活, 3=使用中, 4=已完成, 5=已过期, 6=已作废, 7=更换权益人中）',
  `void_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '作废原因',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_equity_code` (`equity_code`),
  UNIQUE KEY `uk_equity_no` (`equity_no`),
  KEY `idx_batch_code` (`batch_code`),
  KEY `idx_channel_code` (`channel_code`),
  KEY `idx_agent_code` (`agent_code`),
  KEY `idx_client_code` (`client_code`),
  KEY `idx_equity_status` (`equity_status`),
  KEY `idx_expire_time` (`expire_time`),
  KEY `idx_order_code` (`order_code`),
  KEY `idx_carrier_type` (`carrier_type`),
  KEY `idx_goods_code` (`goods_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='权益卡/函库';
/*!40101 SET character_set_client = @saved_cs_client */;

