--
-- Table structure for table `equity_use_person`
--

DROP TABLE IF EXISTS `equity_use_person`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `equity_use_person` (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `equity_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '权益编码',
  `client_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '权益持有人编码（激活权益的客户）',
  `use_person_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '使用人姓名',
  `use_person_gender` tinyint(1) DEFAULT '0' COMMENT '使用人性别（0=未知, 1=男, 2=女）',
  `use_person_birthday` date DEFAULT NULL COMMENT '使用人出生日期',
  `use_person_age` tinyint DEFAULT NULL COMMENT '使用人年龄',
  `use_person_phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '使用人手机号',
  `use_person_id_card` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '使用人身份证号（AES-256-GCM 密文，Base64(IV||ciphertext||tag))',
  `relation_with_holder` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '与持有人关系（本人/配偶/子女/父母/其他）',
  `health_status` text COLLATE utf8mb4_unicode_ci COMMENT '健康状况简述',
  `care_need` text COLLATE utf8mb4_unicode_ci COMMENT '照护需求简述',
  `is_default_holder` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否默认权益人（0=否, 1=是；一张权益仅一人为默认权益人，可被 equity_change_holder 更换）',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  KEY `idx_equity_code` (`equity_code`),
  KEY `idx_client_code` (`client_code`),
  KEY `idx_is_default_holder` (`is_default_holder`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='权益使用人';
/*!40101 SET character_set_client = @saved_cs_client */;

