--
-- Table structure for table `finance_account`
--

DROP TABLE IF EXISTS `finance_account`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `finance_account` (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `account_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '账目编码',
  `direction` tinyint NOT NULL COMMENT '账目方向（1=应收, 2=应付）',
  `account_type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '对象类型（channel/supplier/agent）',
  `target_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '对象编码',
  `target_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '对象名称',
  `biz_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型（字符串枚举：equity_purchase=权益采购, scene_fee=场景费用, service_fee=服务费）',
  `biz_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务编码',
