INSERT INTO `goods_info` VALUES (1,'GD00001','阳光颐养中心参观体验-SC00003','机构参观体验日',2,NULL,NULL,NULL,NULL,NULL,'含场地参观+午餐体验+顾问讲解','深入了解机构环境的一日体验活动',200.00,99.00,NULL,'å…ƒ',-1,0,0,0,NULL,NULL,0,0,0,0,1,0,NULL,'2026-08-05 10:45:43','2026-08-05 10:46:06','AC00001','AC00001',0,NULL),(2,'GD00002','居家养老上门服务套餐-权益版','居家上门1年期',1,'','','','','','包含每月4次上门照护+健康监测','专业居家养老上门服务',1200.00,999.00,NULL,'yuan/month',0,0,0,0,NULL,NULL,0,0,0,0,1,0,'','2026-08-05 12:38:06','2026-08-14 10:20:55','AC00001','AC00001',0,NULL),(3,'GD00003','终身养老权益·个人尊贵版','终身权益个人版',1,'','','','','','【终身养老权益·个人尊贵版】权益人：投保人本人（1人）。\n核心权益：旅居6次/年 + 长居1次/终身 + 照护1次/终身。\n权益内容：旅居优惠权、长居/照护保证入住权、优先入住权、优惠入住权、养老管家服务。\n可转让1次。','投保人本人(1人)：旅居6次/年+长居1次+照护1次/终身，含保证入住权',1000.00,1000.00,NULL,'元/份',0,0,0,0,NULL,NULL,0,0,0,0,1,0,'','2026-08-08 15:54:21','2026-08-14 10:20:33','system','AC00001',0,NULL),(4,'GD00004','终身养老权益·家庭尊享版','终身权益夫妻版',1,'','','','','','【终身养老权益·家庭尊享版】权益人：投保人本人+配偶（2人）。\n核心权益：旅居6次/年 + 长居2次/终身 + 照护2次/终身。\n权益内容：旅居优惠权、长居/照护保证入住权、优先入住权、优惠入住权、养老管家服务。\n支持共享权益。可转让1次。','投保人+配偶(2人)：旅居6次/年+长居2次+照护2次/终身，支持共享',2000.00,2000.00,NULL,'元/份',0,0,0,0,NULL,NULL,0,0,0,0,1,0,'','2026-08-08 15:54:21','2026-08-14 10:20:19','system','AC00001',0,NULL),(5,'GD00005','终身养老权益·豪华3人版','终身权益3人版',1,'','','','','','【终身养老权益·豪华3人版】权益人：3人。\n核心权益：旅居6次/年 + 长居3次/终身 + 照护3次/终身。\n权益内容：旅居优惠权、长居/照护保证入住权、优先入住权、优惠入住权、养老管家服务。\n支持共享权益。可转让2次。','3人共享：旅居6次/年+长居3次+照护3次/终身，可转让2次',3000.00,3000.00,NULL,'元/份',0,0,0,0,NULL,NULL,0,0,0,0,1,0,'','2026-08-08 15:54:21','2026-08-14 10:20:01','system','AC00001',0,NULL),(6,'GD00006','终身养老权益·豪华4人版','终身权益4人版',1,'','','','','','【终身养老权益·豪华4人版】权益人：4人。\n核心权益：旅居6次/年 + 长居4次/终身 + 照护4次/终身。\n权益内容：旅居优惠权、长居/照护保证入住权、优先入住权、优惠入住权、养老管家服务。\n支持共享权益。可转让2次。','4人共享：旅居6次/年+长居4次+照护4次/终身，可转让2次',4000.00,4000.00,NULL,'元/份',0,0,0,0,NULL,NULL,0,0,0,0,1,0,'','2026-08-08 15:54:21','2026-08-14 10:19:45','system','AC00001',0,NULL),(7,'GD00007','终身养老权益·豪华5人版','终身权益5人版',1,'','','','','','【终身养老权益·豪华5人版】权益人：5人。\n核心权益：旅居6次/年 + 长居5次/终身 + 照护5次/终身。\n权益内容：旅居优惠权、长居/照护保证入住权、优先入住权、优惠入住权、养老管家服务。\n支持共享权益。可转让3次。','5人共享：旅居6次/年+长居5次+照护5次/终身，可转让3次',5000.00,5000.00,NULL,'元/份',0,0,0,0,NULL,NULL,0,0,0,0,1,0,'','2026-08-08 15:54:21','2026-08-14 10:19:01','system','AC00001',0,NULL),(8,'GD00008','终身养老权益·至尊6人版','终身权益6人版',1,'','','','','','【终身养老权益·至尊6人版】权益人：6人。\n核心权益：旅居6次/年 + 长居6次/终身 + 照护6次/终身。\n权益内容：旅居优惠权、长居/照护保证入住权、优先入住权、优惠入住权、养老管家服务。\n支持共享权益。可转让3次。','6人共享：旅居6次/年+长居6次+照护6次/终身，可转让3次',6000.00,6000.00,NULL,'元/份',0,0,0,0,NULL,NULL,0,0,0,0,1,0,'','2026-08-08 15:54:21','2026-08-14 10:18:49','system','AC00001',0,NULL),(9,'GD00009','养老管家服务·一年期','管家服务1年期',1,'','','','','','【一年期养老管家服务（电子版）】权益人：本人，可服务于持卡人自己的适龄有养老入住需求的客户。\n核心权益：旅居10次/年 + 长居10次/年 + 照护10次/年。\n权益内容：旅居优惠权（门市价9折）、长居/照护优先入住权、优惠入住权、养老管家服务。\n有效期一年。','旅居10次+长居10次+照护10次/年，旅居门市价9折，管家全程服务',300.00,300.00,NULL,'元/份',0,0,0,0,NULL,NULL,0,0,0,0,1,0,'','2026-08-08 15:54:21','2026-08-14 10:18:29','system','AC00001',0,NULL),(10,'GD00010','旅居随心住·单次版','随心住单次版',4,'','','','','','【旅居随心住·单次版（电子卡）】\n权益人：本人。\n服务内容：在权益卡有效期内，权益人可以在权益范围内的旅居养老机构中任选其中一个，可免费入住1次（最多3天2晚，1间房间，可入住2人）。\n\n入住规则：\n1、出行前请至少提前15天预定；\n2、一张随心住权益卡单次最多预定1套房型房间；\n3、每房间入住人数依房间限制；\n4、需随心住权益人本人到现场办理入住；\n5、春节9天（除夕到初八）不可入住；\n6、每次预定需缴纳500元预定金，于权益人办理入住后1-3个工作日全额退还；\n7、入住前72小时取消，预定金全额退还；入住前48小时取消，预定金退还50%；入住前24小时取消，预定金不予退还。','权益卡有效期内可在旅居养老机构免费入住1次（3天2晚，1间房，可入住2人）',599.00,499.00,NULL,'元/份',0,0,0,0,NULL,NULL,0,1,0,10,1,0,'随心住旅居·单次版（来源：随心住旅居.docx）','2026-08-09 17:48:02','2026-08-14 10:17:58','system','AC00001',0,NULL),(11,'GD00011','旅居随心住·多次版','随心住多次版',4,'','','','','','【旅居随心住·多次版（电子卡）】\n权益人：本人。\n服务内容：在权益卡有效期内，权益人可以在权益范围内的旅居养老机构中任选其中一个，可免费入住3次（每次最多3天2晚，1间房间，可入住2人）。\n\n入住规则：\n1、出行前请至少提前15天预定；\n2、一张随心住权益卡单次最多预定1套房型房间；\n3、每房间入住人数依房间限制；\n4、需随心住权益人本人到现场办理入住；\n5、春节9天（除夕到初八）不可入住；\n6、每次预定需缴纳500元预定金，于权益人办理入住后1-3个工作日全额退还；\n7、入住前72小时取消，预定金全额退还；入住前48小时取消，预定金退还50%；入住前24小时取消，预定金不予退还。','权益卡有效期内可在旅居养老机构免费入住3次（每次3天2晚，1间房，可入住2人）',2999.00,2499.00,NULL,'元/份',0,0,0,0,NULL,NULL,0,1,1,11,1,0,'随心住旅居·多次版（来源：随心住旅居.docx；多次版次数文档未明确，暂按3次/有效期配置，可调整）','2026-08-09 17:48:02','2026-08-14 10:17:47','system','AC00001',0,NULL);
