DROP TABLE IF EXISTS `order_course`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_course` (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `order_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单编号',
  `order_type` tinyint NOT NULL DEFAULT '1' COMMENT '订单类型（1=自主购买, 2=代理人代报, 3=权益兑换）',
  `channel_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '渠道编码',
  `channel_full_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '渠道名称（快照）',
  `agent_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '代理人编码',
  `agent_full_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '代理人姓名（快照）',
  `distributor_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分销商编码（可空）',
  `distributor_full_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分销商名称（快照）',
  `client_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户编码',
  `client_full_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户姓名（快照）',
  `goods_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品编码',
  `goods_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商品名称快照',
  `course_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '课程编码',
  `course_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '课程名称',
  `sku_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SKU 编码',
  `sku_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '规格名称快照',
  `quantity` int NOT NULL DEFAULT '1' COMMENT '购买数量',
  `unit_price` decimal(12,2) NOT NULL COMMENT '单价',
  `total_amount` decimal(14,2) NOT NULL COMMENT '订单总额',
  `discount_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '优惠金额',
  `pay_amount` decimal(14,2) NOT NULL COMMENT '实付金额',
  `coupon_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '优惠券编码',
  `pay_type` tinyint DEFAULT NULL COMMENT '支付方式（pay_type 字典：1=微信支付, 2=支付宝, 3=银行转账, 4=余额支付, 5=线下支付）',
  `pay_time` datetime DEFAULT NULL COMMENT '支付时间',
  `equity_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '使用的权益编码',
  `order_status` tinyint NOT NULL DEFAULT '0' COMMENT '状态（0=待支付, 1=已支付, 2=部分发放, 3=已发放, 4=已完成, 5=已取消, 6=退款中, 7=已退款）',
  `cancel_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '取消原因',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_code` (`order_code`),
  KEY `idx_course_code` (`course_code`),
  KEY `idx_client_code` (`client_code`),
  KEY `idx_order_status` (`order_status`),
  KEY `idx_channel_code` (`channel_code`),
  KEY `idx_distributor_code` (`distributor_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='课程订单';
