--
-- Table structure for table `park_adviser`
--

DROP TABLE IF EXISTS `park_adviser`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `park_adviser` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `park_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '机构编码',
  `adviser_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '顾问姓名',
  `adviser_title` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '顾问头衔（如"资深顾问"、"护理主管"）',
  `adviser_image` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '顾问照片URL',
  `adviser_content` text COLLATE utf8mb4_unicode_ci COMMENT '顾问介绍/专业背景',
  `contact_phone` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '顾问联系电话',
  `is_primary` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否首席顾问（0=否, 1=是）',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序号',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态（0=隐藏, 1=显示）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  KEY `idx_park_code` (`park_code`),
  KEY `idx_is_primary` (`is_primary`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='机构顾问信息';
/*!40101 SET character_set_client = @saved_cs_client */;

