LOCK TABLES `park_adviser` WRITE;
/*!40000 ALTER TABLE `park_adviser` DISABLE KEYS */;
INSERT INTO `park_adviser` VALUES (1,'PK00003','张磊','和园顾问','park/migration/2026/08/08/pk00003_adv_000.png','和园现在人少但环境打造基本齐备，早入住的用户可以抢先获得入住的清幽福利，公共资源享受更全面。欢迎下方预约参观！',NULL,1,1,1,'2026-08-09 10:01:06','2026-08-09 10:01:06','system','system',0,NULL);
