--
-- Table structure for table `park_asset`
--

DROP TABLE IF EXISTS `park_asset`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `park_asset` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `park_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '机构编码',
  `asset_type` tinyint NOT NULL COMMENT '素材类型（1=图片 2=视频 3=文件 4=VR）',
  `asset_url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件 OSS key（存 key 非完整 URL）',
  `asset_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件名称',
  `asset_category` tinyint DEFAULT NULL COMMENT '业务分类（图片:1=外观..11=其他 视频:1=宣传..3=活动 文件:1=资质..5=其他 VR:1=全景..3=视频VR）',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `file_size` bigint DEFAULT NULL COMMENT '文件大小（字节）',
  `width` int DEFAULT NULL COMMENT '图片宽度px（图片专属）',
  `height` int DEFAULT NULL COMMENT '图片高度px（图片专属）',
  `is_cover` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否封面（图片专属 0=否 1=是）',
  `cover_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面图key（视频专属）',
  `duration` int DEFAULT NULL COMMENT '时长秒（视频专属）',
  `file_format` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件格式（文件专属 pdf/doc/xls等）',
  `vr_provider` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'VR服务提供商（VR专属）',
  `thumbnail_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '缩略图key（VR专属）',
  `source_type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'media_mgmt' COMMENT '来源（media_mgmt=素材库直传 room_type=房型 food_type=餐饮 facility=设施 service_item=服务 display_block=展示板块 adviser=顾问 park_info=机构信息）',
  `source_ref_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源编码（media_mgmt 时为 NULL）',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序号',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态（0=隐藏 1=显示）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  KEY `idx_park_type` (`park_code`,`asset_type`,`sort_order`),
  KEY `idx_source` (`source_type`,`source_ref_code`),
  KEY `idx_asset_url` (`asset_url`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=692 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='机构素材库（统一管理所有来源的图片/视频/文件/VR）';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `park_asset`
--

