DROP TABLE IF EXISTS `park_care_type`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `park_care_type` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `park_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '机构编码',
  `care_type_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '照护类型编码',
  `care_type_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '照护类型名称（如"自理型"、"半失能"、"失能"、"失智"）',
  `care_level` tinyint NOT NULL DEFAULT '1' COMMENT '照护等级（1=特级护理, 2=一级护理, 3=二级护理, 4=三级护理, 5=生活自理）',
  `care_target` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '适用人群描述',
  `care_items` text COLLATE utf8mb4_unicode_ci COMMENT '护理项目明细（JSON数组）',
  `care_frequency` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '护理频次（如"每日3次"、"24小时"）',
  `nurse_patient_ratio` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '护患比（如"1:3"）',
  `assessment_criteria` text COLLATE utf8mb4_unicode_ci COMMENT '评估标准说明',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '照护类型详细描述',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序号',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态（0=停售, 1=在售）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_care_type_code` (`park_code`,`care_type_code`),
  KEY `idx_park_code` (`park_code`),
  KEY `idx_care_level` (`care_level`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='养老机构照护类型';
/*!40101 SET character_set_client = @saved_cs_client */;

