DROP TABLE IF EXISTS `park_display_block`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `park_display_block` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `park_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '机构编码',
  `block_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '板块类型',
  `block_title` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '板块标题',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '富文本内容（HTML）',
  `images` text COLLATE utf8mb4_unicode_ci COMMENT '图片key列表（JSON数组）',
  `image_descriptions` text COLLATE utf8mb4_unicode_ci COMMENT '图片描述列表（JSON数组）',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序号',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态（0=隐藏, 1=显示）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  KEY `idx_park_code` (`park_code`),
  KEY `idx_park_type` (`park_code`,`block_type`)
) ENGINE=InnoDB AUTO_INCREMENT=80 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='机构展示内容板块（C端详情页）';
