INSERT INTO `park_display_block` VALUES (1,'PK00001','live_env','居住环境(已更新)','<p>updated</p>','[\"park/test1.jpg\"]','[\"hall\"]',2,1,'2026-08-08 22:04:40','2026-08-08 22:04:47','AC00001','AC00001',1,NULL),(2,'PK00001','entertainment','文娱生活展示（API编辑）','<p>updated via API</p>','[]','[]',3,1,'2026-08-08 22:05:59','2026-08-08 22:09:06','AC00001','AC00001',1,NULL),(3,'PK00003','entertainment','文娱生活','社区中心有各类活动设施，在琴棋书画中陶冶情操，在瑜伽室台球室里锻炼身体，在精美手工活动中锻炼手脑，在椿萱学堂中继续提升自己，在功能厅里一起做操参加晚会。好多想做的事都有了条件','[\"park/migration/2026/08/08/pk00003_ent_000.png\", \"park/migration/2026/08/08/pk00003_ent_001.png\", \"park/migration/2026/08/08/pk00003_ent_002.png\", \"park/migration/2026/08/08/pk00003_ent_003.png\", \"park/migration/2026/08/08/pk00003_ent_004.png\"]',NULL,1,1,'2026-08-09 10:00:54','2026-08-09 10:00:54','system','system',0,NULL),(4,'PK00003','health_status','康养状况','<p>◆ 内设医务室，有24小时医护服务，未来可对接社保，满足长辈日常取药、打针、输液需求；</p><p>◆ 定期中医院专家坐诊（北京中医医院顺义分院）；</p><p>◆ 999急救站进驻；</p><p>◆ 由专业医护团队通过周期性定制化服务，从“保持健康、管理慢病、防控风险”，三大层面，全维度守护长者身心。</p>','[\"park/migration/2026/08/08/pk00003_health_000.png\", \"park/migration/2026/08/08/pk00003_health_001.png\", \"park/migration/2026/08/08/pk00003_health_002.png\"]',NULL,2,1,'2026-08-09 10:00:54','2026-08-09 10:00:54','system','system',0,NULL),(5,'PK00004','entertainment','文娱生活','九华山庄贵宾楼酒店是中国养生和休闲文化的集大成者。温榆会馆内拥有40余间豪华VIP包间、泰式按摩房、美容美体房，以及多个独立户外温泉泡池、电动按摩浴缸等设施，可为宾客提供温泉SPA、各式按摩、康复理疗等多种专业保健养生服务。会馆中还配备有豪华健身房、游泳池、以及霓裳歌舞总会等时尚运动娱乐设施，尽享高品质休闲生活的尊贵与乐趣。','[\"park/migration/2026/08/08/pk00004_ent_000.png\", \"park/migration/2026/08/08/pk00004_ent_001.png\", \"park/migration/2026/08/08/pk00004_ent_002.png\", \"park/migration/2026/08/08/pk00004_ent_003.png\", \"park/migration/2026/08/08/pk00004_ent_004.png\", \"park/migration/2026/08/08/pk00004_ent_005.png\", \"park/migration/2026/08/08/pk00004_ent_006.png\"]',NULL,1,1,'2026-08-09 10:00:54','2026-08-09 10:00:54','system','system',0,NULL),(6,'PK00004','health_status','康养状况','配有一级综合医院（北京市医保定点医院），下设：内科、外科、口腔、中医理疗等科室，有完善的体检体系，CT，核磁等。专业护理配套占总床位20%左右，全程为老人的健康保驾护航','[\"park/migration/2026/08/08/pk00004_health_000.png\", \"park/migration/2026/08/08/pk00004_health_001.png\", \"park/migration/2026/08/08/pk00004_health_002.png\", \"park/migration/2026/08/08/pk00004_health_003.png\", \"park/migration/2026/08/08/pk00004_health_004.png\"]',NULL,2,1,'2026-08-09 10:00:54','2026-08-09 10:00:54','system','system',0,NULL),(7,'PK00005','entertainment','文娱生活','专职护工亲情陪伴，设有书画、手工、阅读、棋牌等多功能厅，享受丰盛人生','[\"park/migration/2026/08/08/pk00005_ent_000.png\", \"park/migration/2026/08/08/pk00005_ent_001.png\", \"park/migration/2026/08/08/pk00005_ent_002.png\"]',NULL,1,1,'2026-08-09 10:00:54','2026-08-09 10:00:54','system','system',0,NULL),(8,'PK00005','health_status','康养状况','主要为失能/半失能、长期卧床、术后康复、高龄颐养、慢病调理等长者提供标准化、精细化、智慧化的康养与照护服务。\\n严格按照国家标准，提供适老精细化服务，为长者提供无微不至的全天候照护\\n与首都医科大学复兴医院一墙之隔，方便长者就医取药，守护长者健康无忧','[\"park/migration/2026/08/08/pk00005_health_000.png\", \"park/migration/2026/08/08/pk00005_health_001.png\", \"park/migration/2026/08/08/pk00005_health_002.png\", \"park/migration/2026/08/08/pk00005_health_003.png\", \"park/migration/2026/08/08/pk00005_health_004.png\", \"park/migration/2026/08/08/pk00005_health_005.png\"]',NULL,2,1,'2026-08-09 10:00:54','2026-08-09 10:00:54','system','system',0,NULL),(9,'PK00006','entertainment','文娱生活','<p>（1）洞察长者心理需求，丰富精神生活，书写精彩晚年</p><p>关注长者心理需求，开展丰富的日常活动。中心配置6大主题互动空间供长者娱乐休闲，同时在节日、假日不定期开展大型活动，鼓励长者社交与学习，激发长者正向情绪，切实提高长者精神生活质量，让长者在保留社会性的同时，做到老有所学、老有所乐、老有所为。</p><p>（2）6大主题互动空间，安享闲适时光</p><p>①多媒体室</p><p>多媒体室会根据不同的时间，安排音乐会和经典电影鉴赏，也会作为悦年华老年大学的多功能教室，在节日或开放日还会举办丰富多彩的乐龄文化活动。</p><p>②多功能室</p><p>多功能室是为长者提供的独立活动空间，同时还可以满足家庭独立团聚需求，并可以提供独立家庭及生日聚餐使用。</p><p>③棋牌室</p><p>棋牌室配备象棋、军旗、扑克、麻将等娱乐设施，每月举办不同的休闲比赛，乐趣横生，益智休闲。</p><p>④舞蹈室</p><p>舞蹈室聘请老年舞蹈教师定期开课，培养长者兴趣，提高长者的运动机能，让长者通过兴趣运动，获得身心平衡。</p><p>⑤书画室</p><p>定期举办书画活动，为长者提供绘画书法的教学和交流活动场地，修身养性乐在其中。</p><p>⑥时光景观花园</p><p>独立园林景观花园，为长者提供多种户外休闲设施，满足长者户外活动需求，提供更好的颐养氛围。</p>','[\"park/migration/2026/08/08/pk00006_ent_000.png\", \"park/migration/2026/08/08/pk00006_ent_001.png\"]',NULL,1,1,'2026-08-09 10:00:54','2026-08-09 10:00:54','system','system',0,NULL),(10,'PK00006','health_status','康养状况','<p>（1）医养+康养健康生态，整合全球医疗资源</p><p>华润置地整合集团专业健康三大板块华润健康、华润医疗与华润医药，共享旗下拥有的118家医疗机构，涵盖6家三级医院、14家二级医院、28家一级医院和华润医药的研产销产业链综合业务能力以及丰富医药相关资源。</p><p>（2）专业医疗团队，满足长者康复需求</p><p>悦年华·颐养中心（北京瀛海）拥有医务室、康复室、感统治疗室三大医疗设施，并配备医生、护士、康复师专业医疗团队，时刻关注长者健康。</p><p>（3）权威机构合作，共享长者健康管理</p><p>华润置地整合集团专业健康三大板块华润健康、华润医疗与华润医药，共享旗下拥有的118家医疗机构，涵盖6家三级医院、14家二级医院、28家一级医院和华润医药的研产销产业链综合业务能力以及丰富医药相关资源。</p><p>（4）周边医疗支持，长者健康一步到位</p><p>悦年华·颐养中心（北京瀛海）与周边所有二级以上医院、社区医院建立密切合作，随时就医、取药快速便捷。项目距大兴中西医结合医院（三级）3公里，距同仁医院南院区（ 三甲）7公里，10公里范围内分布有5家医疗机构。</p><p>（5）核心医疗资源，保证专业康养服务</p><p>悦年华·颐养中心（北京瀛海）联合华润健康体系、北京301医院、北京协和医院等多家权威医疗机构，并与专业研究机构、神经内科科室和认知障碍领域的专家建立密切合作。以医疗顾问形式完善院内医疗、医养需求。同时建立远程问诊机制，让长者的健康得到高专业度、高品质的医疗保障。</p><p>（6）按照标准康复医院功能进行规划建设的康复医疗中心，配备专业康复师坐诊，为长者进行专业康复指导，致力于为长者提供更加完善的健康解决方案，用合理的康复训练及运动帮助长者保持健康。</p>','[\"park/migration/2026/08/08/pk00006_health_000.png\"]',NULL,2,1,'2026-08-09 10:00:54','2026-08-09 10:00:54','system','system',0,NULL),(11,'PK00007','health_status','康养状况','自建一流的专业运营团队:由拥有近10年高端养老服务经验的专业人员领衔。护理团队具备高端养老经验，部分人员具有三甲医院及海内外高端养老服务从业经验。新华家园护理团队打造的高端专业护理服务，为长者提供高品质的城市养老生活，让长者尊享晚年生活的新篇章。','[\"park/migration/2026/08/08/pk00007_health_000.png\", \"park/migration/2026/08/08/pk00007_health_001.png\"]',NULL,2,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(12,'PK00008','entertainment','文娱生活','“丰富多彩”的业余生活：影视剧鉴赏，讲座活动，节庆活动，老少乐寿会，旅游服务，康宁老年大学，有书画室、图书阅览室、棋牌室、练歌房、音乐教室、健身房、舞蹈教室、乒乓球/台球室、多功能厅、活动室、阳光房等休闲文化娱乐设施，户外活动等。','[\"park/migration/2026/08/08/pk00008_ent_000.jpg\", \"park/migration/2026/08/08/pk00008_ent_001.jpg\", \"park/migration/2026/08/08/pk00008_ent_002.jpg\", \"park/migration/2026/08/08/pk00008_ent_003.jpg\", \"park/migration/2026/08/08/pk00008_ent_004.jpg\", \"park/migration/2026/08/08/pk00008_ent_005.jpg\", \"park/migration/2026/08/08/pk00008_ent_006.jpg\", \"park/migration/2026/08/08/pk00008_ent_007.jpg\", \"park/migration/2026/08/08/pk00008_ent_008.jpg\"]',NULL,1,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(13,'PK00008','health_status','康养状况','“健康管理中心”配备专属的健康秘书，每年为长者体检，建立个人健康档案，对每一位长者的身 体状况进行专业的健康检测、健康评估和健康干预，制定以“治未病”为主的个性化健康管理方案。','[\"park/migration/2026/08/08/pk00008_health_000.png\", \"park/migration/2026/08/08/pk00008_health_001.png\", \"park/migration/2026/08/08/pk00008_health_002.png\", \"park/migration/2026/08/08/pk00008_health_003.png\", \"park/migration/2026/08/08/pk00008_health_004.png\", \"park/migration/2026/08/08/pk00008_health_005.png\", \"park/migration/2026/08/08/pk00008_health_006.png\", \"park/migration/2026/08/08/pk00008_health_007.png\"]',NULL,2,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(14,'PK00009','entertainment','文娱生活','开设长者学院，最大限度激发长者活力，帮助长者启迪心灵、增长知识、陶冶情操、拓宽视野。\\n设置艺术长廊、书画社区、制作工坊、拍卖展示区。开展丰富多彩的艺术交流活动如培训、展览、展示、比赛、艺术节、公益拍卖等，丰富长者文化生活。\\n开设长者学院，最大限度激发长者活力，帮助长者启迪心灵、增长知识、陶冶情操、拓宽视野，使学院成为长者延缓衰老、永葆活力的精神家园。\\n采用国际标准的老年综合评估体系，对长者身体状况、心理健康、社会功能、自身现存及潜在的健康风险等进行综合评估。\\n设置棋牌、麻将、健身、乒乓球、台球、沙狐球、门球、游泳、温泉水疗、卡拉 OK、室内高尔夫、电影剧场、图书阅览、水吧茶室、祷告静修、超市购物、美容美发、幼儿照护、健身广场、多功能室等活动场所。不定期举办大型艺术节活动，邀请包括音乐、舞蹈、戏剧等各领域中的顶尖人士以及深具潜力的新秀，让长者享受艺术活力和创新精神。','[\"park/migration/2026/08/08/pk00009_ent_000.png\", \"park/migration/2026/08/08/pk00009_ent_001.png\", \"park/migration/2026/08/08/pk00009_ent_002.png\", \"park/migration/2026/08/08/pk00009_ent_003.png\"]',NULL,1,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(15,'PK00009','health_status','康养状况','采用国际标准的老年综合评估体系，对长者身体状况、心理健康、社会功能、自身现存及潜在的健康风险等进行综合评估。\\n除社区自建医疗康复中心外，还与北京协和、解放军总医院等多个三甲医院合作，建立绿色通道、实现双向转诊，开展专家坐诊、巡诊服务，建设健康管理中心、老年康复、中医康复、呼吸康复等特色康复中心，提供急救保障、慢病管理、康复保健，实现全人医疗，为老人提供生理、功能、心理和社会等全方位的医疗保健服务。','[\"park/migration/2026/08/08/pk00009_health_000.png\", \"park/migration/2026/08/08/pk00009_health_001.png\"]',NULL,2,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(16,'PK00010','entertainment','文娱生活','大爱书院打造约13000㎡中心会所，设置有大爱藏书室、手工活动室、健身房、游泳池等一站式养老文化活动空间，同时开设丰富课程以及定制旅居游学，实现老有所教、老有所学、老有所为、老有所乐。','[\"park/migration/2026/08/08/pk00010_ent_000.png\", \"park/migration/2026/08/08/pk00010_ent_001.png\", \"park/migration/2026/08/08/pk00010_ent_002.png\", \"park/migration/2026/08/08/pk00010_ent_003.png\", \"park/migration/2026/08/08/pk00010_ent_004.png\", \"park/migration/2026/08/08/pk00010_ent_005.png\", \"park/migration/2026/08/08/pk00010_ent_006.png\", \"park/migration/2026/08/08/pk00010_ent_007.png\", \"park/migration/2026/08/08/pk00010_ent_008.png\", \"park/migration/2026/08/08/pk00010_ent_009.png\", \"park/migration/2026/08/08/pk00010_ent_010.png\"]',NULL,1,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(17,'PK00010','health_status','康养状况','整合香河大爱书院养老中心医务室、香河大爱医疗中心、香河大爱康复医院（建设中）、国内三甲医院资源为主体，打造四级医疗联诊体系，为长者提供健康医疗、在线就医、慢病管理、紧急救助等多维医疗服务保障。','[\"park/migration/2026/08/08/pk00010_health_000.png\"]',NULL,2,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(18,'PK00011','entertainment','文娱生活','温泉水疗、电影院、亲子乐园、养生大讲堂、棋牌室、禅修室、会员活动中心（每日均有不同活动安排，多达20种以上）','[\"park/migration/2026/08/08/pk00011_ent_000.png\", \"park/migration/2026/08/08/pk00011_ent_001.png\", \"park/migration/2026/08/08/pk00011_ent_002.png\", \"park/migration/2026/08/08/pk00011_ent_003.png\", \"park/migration/2026/08/08/pk00011_ent_004.png\", \"park/migration/2026/08/08/pk00011_ent_005.png\", \"park/migration/2026/08/08/pk00011_ent_006.png\"]',NULL,1,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(19,'PK00011','health_status','康养状况','由海南卫健委批准设立的一级医疗机构。\\n开创无癌雨林呼吸系统慢病调理治疗法、氢分子医学、功能理疗等康复医疗项目。','[\"park/migration/2026/08/08/pk00011_health_000.png\", \"park/migration/2026/08/08/pk00011_health_001.png\", \"park/migration/2026/08/08/pk00011_health_002.png\", \"park/migration/2026/08/08/pk00011_health_003.png\", \"park/migration/2026/08/08/pk00011_health_004.png\", \"park/migration/2026/08/08/pk00011_health_005.png\", \"park/migration/2026/08/08/pk00011_health_006.png\", \"park/migration/2026/08/08/pk00011_health_007.png\"]',NULL,2,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(20,'PK00012','entertainment','文娱生活','<p>知心娱乐：悦年华•长沙天心颐养中心（天心区社会福利中心）内设书画室、阅读室、棋牌室、影音室等各种兴趣活动室，为长者提供展示的舞台；专设社工岗位，科学规划长者活动；重要节庆日举办展览、比赛、游戏等，在缤纷多彩的文娱生活中，快乐养生、精致养老。</p>','[\"park/migration/2026/08/08/pk00012_ent_000.png\", \"park/migration/2026/08/08/pk00012_ent_001.jpg\", \"park/migration/2026/08/08/pk00012_ent_002.jpg\"]',NULL,1,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(21,'PK00012','health_status','康养状况','<p>1、健康管理：医护日查房，对每位长者建档；根据健康状况，对呼吸、体温、脉搏、血压基本四项、以及血糖、血氧等指征监测；药物集中管理；基础病、常见病基本治疗不出院。</p><p>2、贴心养老：配备年轻化高素质养老团队，结合气候及长者作息情况，科学规划长者每日生活，定期查房，鼓励长者活动筋骨，让长者享受悠然自得的晚年生活，为长者提供真正贴心、实用、安全舒适的起居照护体验。</p><p>3、精心康复：精准呵护，实现健康动态管理。入住前为长者提供全面健康综合评估，依据评估结果制定精准的养护方案，入住过程中持续关注长者健康，防控健康风险，实现长者的专属健康动态管理。</p><p>4、耐心护理：依托资深医护团队，可为长期卧床、疾病末期的失能失智长者提供精细化、专业化的护理服务。以自立支援、身心并护的服务理念，为长者提供全方位照护服务。</p>','[\"park/migration/2026/08/08/pk00012_health_000.png\", \"park/migration/2026/08/08/pk00012_health_001.png\", \"park/migration/2026/08/08/pk00012_health_002.png\", \"park/migration/2026/08/08/pk00012_health_003.jpg\"]',NULL,2,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(22,'PK00013','entertainment','文娱生活','<p>太湖椿2幢楼至18幢楼为乐活银龄住区，共715户，其中2幢高层，13幢洋房，全屋精装修适老化设计，营造“五园八境”，打造低密乐活养老社区，为长辈提供健康医疗、膳食特配、居家保障、专属管家、尊享定制、休闲文娱、生态疗养7大类70余项“七彩鑫怡”特色服务，开启享老新生活。</p><p>住区内每幢都打造了沉浸式共享公区和全景长者社交空间，通过“金凰展翼”布局，以鑫颐学院为中心轴，享有超16000平方米公区配套，两翼通过风雨连廊串联有氧运动空间、手工兴趣角等，搭配恒温泳池、颐养汤池、两大主题餐厅等，园区景观以“善意”为核心诉求，以“适老化”为设计标准，形成真正的情境共融的沉浸式全景长者社群休闲平台，共享有人、有景、有情、有味的美好银龄。</p>','[\"park/migration/2026/08/08/pk00013_ent_000.jpg\", \"park/migration/2026/08/08/pk00013_ent_001.jpg\", \"park/migration/2026/08/08/pk00013_ent_002.jpg\", \"park/migration/2026/08/08/pk00013_ent_003.jpg\", \"park/migration/2026/08/08/pk00013_ent_004.jpg\", \"park/migration/2026/08/08/pk00013_ent_005.jpg\", \"park/migration/2026/08/08/pk00013_ent_006.jpg\", \"park/migration/2026/08/08/pk00013_ent_007.jpg\", \"park/migration/2026/08/08/pk00013_ent_008.jpg\", \"park/migration/2026/08/08/pk00013_ent_009.jpg\"]',NULL,1,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(23,'PK00013','health_status','康养状况','<p>椿怡护理院总建面约1万余平米，设置综合区、护理区（拥有79个床位）、养老区（拥有253个床位）、认知症专区四大区域，为长者提供基础医疗、特色康复、生活照料、专业护理、认知症照护等功能服务，营造场景温馨、服务门类健全的颐养家园。</p><p>综合区（1楼）：设有门诊、内科、中医科、康复医学科、活动大厅、健康评估室、药房，可满足长者们的日常生活及医疗需求。</p><p>护理区（2-5楼）：提供疾病治疗、生活照料、专业护理及特色康复服务，协助照料（半护理/全护理）长者安然度过晚年时光。</p><p>养老区（6-9楼）：提供介护服务，为高龄长者提供生活上的持续性照料，心理上的关怀服务。</p><p>认知症专区（10楼）：运用园艺疗法、怀旧疗法、玩偶疗法、宠物疗法、音乐疗法、香薰疗法、多感官刺激疗法等认知症照护疗法延缓认知能力下降。</p><p>从护理院到浙江鑫达医院急诊入口设有黄金救援通道，在突发情况下，为老人赢得最宝贵的黄金教治时间。</p>','[\"park/migration/2026/08/08/pk00013_health_000.jpg\"]',NULL,2,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(24,'PK00014','entertainment','文娱生活','<p>娱乐设施：棋牌室、电影院、健身房、书画室、阅览室、电脑室、多功能活动室等</p><p>娱乐服务：兴趣班、节日活动、才艺展示等</p>','[\"park/migration/2026/08/08/pk00014_ent_000.jpg\", \"park/migration/2026/08/08/pk00014_ent_001.jpg\", \"park/migration/2026/08/08/pk00014_ent_002.jpg\"]',NULL,1,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(25,'PK00014','health_status','康养状况','<p>柳州东城海阳颐养中心共包含132间起居室及配套用房，共设居室床位370多位，其中A座近190张木质起居床，海阳集团标准化模式的输出，结合物联网、互联网技术，不仅在服务模式上进行创新，同时在运营管理全过程，通过海阳智慧云平台实现医疗服务、生活照料、健康管理、实时监护等保障。</p><p>柳州东城海阳颐养中心的A座近190张木质起居床，B座近180张智能化遥控医疗床并配套相应的适老化设施和服务，致力于为入住长者提供24H管家式服务，专业医养融合照护，提供全方位的生活照料，提升养老生活的幸福感。其中，值得一提的是，海阳集团数智化养老一失能失智长者照料区域位于B座2-3层，数智化养老照护中心为认知障碍长者及家庭提供专业、温暖、持续全程医养融合、数智化照护。</p>','[\"park/migration/2026/08/08/pk00014_health_000.jpg\"]',NULL,2,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(26,'PK00016','entertainment','文娱生活','<p>项目提供书吧、书画室、美食沙龙、棋牌室、乒乓球室、健身房、舞蹈室、声乐室、桌球室、电影院、多功能教室、理发室等配套设施，搭配香树湾俱乐部和文艺大学课程教学服务，保证长者每天充实又开心。</p>','[\"park/migration/2026/08/08/pk00016_ent_000.jpg\", \"park/migration/2026/08/08/pk00016_ent_001.jpg\", \"park/migration/2026/08/08/pk00016_ent_002.jpg\", \"park/migration/2026/08/08/pk00016_ent_003.jpg\", \"park/migration/2026/08/08/pk00016_ent_004.png\", \"park/migration/2026/08/08/pk00016_ent_005.png\", \"park/migration/2026/08/08/pk00016_ent_006.png\"]',NULL,1,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(27,'PK00016','health_status','康养状况','<p>医疗：配有专业医疗资源，养护院，护理院，高压氧舱，氢舱等国外进口设备</p>','[\"park/migration/2026/08/08/pk00016_health_000.png\"]',NULL,2,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(28,'PK00017','entertainment','文娱生活','<p>养老公寓中有书法室、阅读室、棋艺室、桌球室、篮球场、羽毛球场、瑜伽教室、足浴房等适合老年人休闲的娱乐设施。根据自身地理优势挖掘了一条人工河，同时依河而建了一条人行步道。</p>','[\"park/migration/2026/08/08/pk00017_ent_000.jpg\", \"park/migration/2026/08/08/pk00017_ent_001.jpg\", \"park/migration/2026/08/08/pk00017_ent_002.jpg\", \"park/migration/2026/08/08/pk00017_ent_003.jpg\", \"park/migration/2026/08/08/pk00017_ent_004.jpg\", \"park/migration/2026/08/08/pk00017_ent_005.jpg\", \"park/migration/2026/08/08/pk00017_ent_006.jpg\", \"park/migration/2026/08/08/pk00017_ent_007.jpg\", \"park/migration/2026/08/08/pk00017_ent_008.jpg\", \"park/migration/2026/08/08/pk00017_ent_009.jpg\", \"park/migration/2026/08/08/pk00017_ent_010.jpg\", \"park/migration/2026/08/08/pk00017_ent_011.jpg\", \"park/migration/2026/08/08/pk00017_ent_012.jpg\", \"park/migration/2026/08/08/pk00017_ent_013.jpg\", \"park/migration/2026/08/08/pk00017_ent_014.jpg\", \"park/migration/2026/08/08/pk00017_ent_015.jpg\", \"park/migration/2026/08/08/pk00017_ent_016.jpg\", \"park/migration/2026/08/08/pk00017_ent_017.jpg\", \"park/migration/2026/08/08/pk00017_ent_018.jpg\"]',NULL,1,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(29,'PK00017','health_status','康养状况','<p>以“一切为了老年病人”和“救死扶伤，全心全意为人民服务”为办院宗旨，以宝罗护理院专业团队为基础，以区域二级医院和医学会员单位的医疗专家队伍为依托，以先进的医疗技术和诊疗设备为手段，引进先进的医疗管理和服务理念，向当地居民及其周边地区提供高档次、多层次、多样化的医疗及康复服务，努力创造社会效益和经济效益，推动嘉定区的医疗技术与服务水平再上新台阶。</p>','[\"park/migration/2026/08/08/pk00017_health_000.jpg\", \"park/migration/2026/08/08/pk00017_health_001.png\", \"park/migration/2026/08/08/pk00017_health_002.png\"]',NULL,2,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(30,'PK00018','entertainment','文娱生活','<p>设有阅览室、手工室、书画室桌球室、欢唱室、影音室、健身室等文化娱乐设施；</p><p>组织老人参加各类文娱集体活动、陪老人沟通聊天、为老人做心里咨询和心里慰藉等服务。</p>','[\"park/migration/2026/08/08/pk00018_ent_000.jpg\", \"park/migration/2026/08/08/pk00018_ent_001.jpg\", \"park/migration/2026/08/08/pk00018_ent_002.jpg\", \"park/migration/2026/08/08/pk00018_ent_003.jpg\", \"park/migration/2026/08/08/pk00018_ent_004.jpg\", \"park/migration/2026/08/08/pk00018_ent_005.jpg\", \"park/migration/2026/08/08/pk00018_ent_006.jpg\", \"park/migration/2026/08/08/pk00018_ent_007.jpg\"]',NULL,1,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(31,'PK00018','health_status','康养状况','<p>内设医疗机构专区（中西药房、针灸推拿、理疗、化验室、医生诊室），并设有康复中心，配置专业康复理疗设备。</p>','[\"park/migration/2026/08/08/pk00018_health_000.jpg\"]',NULL,2,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(32,'PK00019','entertainment','文娱生活','<p>院内娱乐活动区域有跳操室、阅览室、影视厅、麻将棋牌室、球类活动室等，每月还会不定期地举办各类活动，力争让老人的日常生活变得丰富多彩。</p>','[\"park/migration/2026/08/08/pk00019_ent_000.jpg\", \"park/migration/2026/08/08/pk00019_ent_001.jpg\", \"park/migration/2026/08/08/pk00019_ent_002.jpg\", \"park/migration/2026/08/08/pk00019_ent_003.jpg\", \"park/migration/2026/08/08/pk00019_ent_004.jpg\"]',NULL,1,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(33,'PK00019','health_status','康养状况','<p>院内有内设医疗机构，还有医疗康复区域和药房，可以使用医保，满足了老人的日常诊疗和配药需求。</p><p>复旦大学中山医院吴淞中心医院距离本院1.9公里，仅5分钟车程，与本院签署互联网合作医院、绿色通道；宝山区中西医结合医院距离本院3公里，车程10分钟；第九人民医院北院距离本院3.6公里，车程10分钟左右。</p>','[\"park/migration/2026/08/08/pk00019_health_000.jpg\", \"park/migration/2026/08/08/pk00019_health_001.jpg\", \"park/migration/2026/08/08/pk00019_health_002.jpg\", \"park/migration/2026/08/08/pk00019_health_003.jpg\", \"park/migration/2026/08/08/pk00019_health_004.jpg\"]',NULL,2,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(34,'PK00020','entertainment','文娱生活','<p>养老院设有棋牌室、书画室、多功能厅、阅览室等。每天上午九点半做操，然后是手势舞等集体活动，下午是麻将牌、象棋和唱歌 还有诗社和看电影。</p>','[\"park/migration/2026/08/08/pk00020_ent_000.jpg\", \"park/migration/2026/08/08/pk00020_ent_001.jpg\", \"park/migration/2026/08/08/pk00020_ent_002.jpg\", \"park/migration/2026/08/08/pk00020_ent_003.jpg\", \"park/migration/2026/08/08/pk00020_ent_004.jpg\", \"park/migration/2026/08/08/pk00020_ent_005.jpg\", \"park/migration/2026/08/08/pk00020_ent_006.jpg\", \"park/migration/2026/08/08/pk00020_ent_007.jpg\"]',NULL,1,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(35,'PK00021','entertainment','文娱生活','<p><span style=\"color: rgb(0, 0, 0);\">开发多种针对认知症长者的非药物干预活动，让长者在生活活动中起到锻炼认知能力，延缓认知衰退的效果。</span></p>','[\"park/migration/2026/08/08/pk00021_ent_000.jpeg\", \"park/migration/2026/08/08/pk00021_ent_001.jpeg\", \"park/migration/2026/08/08/pk00021_ent_002.jpeg\"]',NULL,1,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(36,'PK00021','health_status','康养状况','<p style=\"text-align: start;\">实行照护服务标准化流程，专业照护团队24小时全时守护，开设中医穴位按摩等专业中医康复护理服务，开设二甲医院以上及护理院绿色转诊通道，为认知症长者们保驾护航。</p><p>开发多种针对认知症长者的非药物干预活动，让长者在生活活动中起到锻炼认知能力，延缓认知衰退的效果。</p><p>荣上记忆家园着力打造“生活康复和认知康复”特色服务，将康复与环境、日常生活照料、非药物干预活动进行融合，照护服务中处处有细节、处处有专业。</p>','[\"park/migration/2026/08/08/pk00021_health_000.png\"]',NULL,2,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(37,'PK00022','health_status','康养状况','<p>社区内部建设专属医务机构，设置内科，康复科，中医科等各类科室，为长者提供日常的健康评估、用药指导、日常慢病管理、辅助康复等服务。社区以医务室为平台，构建三级诊疗绿通服务、社区长护险、基本医疗保险结算服务等。</p><p>设置专属康复治疗区，聘请专业复合型康复医学治疗团队，为长者提供康复评估、计划制定等全流程康复体系，通过物理治疗、心理辅助治疗、作业治疗、言语治疗、中医治疗等多种康复治疗方法，为长者提供专业有效的康复治疗服务。</p><p>组建了一支由内科医生、康复医生、中医医生、临床护士、康复师、营养师等组成的多学科专业团队。</p>','[\"park/migration/2026/08/08/pk00022_health_000.jpeg\", \"park/migration/2026/08/08/pk00022_health_001.jpeg\"]',NULL,2,1,'2026-08-09 10:00:55','2026-08-09 10:00:55','system','system',0,NULL),(38,'PK00020','live_env','居住环境','<p>地上建筑局部5层，局部7层 六层有一个600平米的大露台，老人可以晒太阳。内部适老化设施完备，房间内有紧急呼救，卫生间有紧急呼救，地面是防滑地胶，楼道和卫生间有安全扶手。</p>','[\"park/migration/2026/08/08/pk00020_env_136.png\", \"park/migration/2026/08/08/pk00020_env_137.png\", \"park/migration/2026/08/08/pk00020_env_138.png\"]',NULL,4,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(39,'PK00020','catering','餐饮服务','<p>提供三次正餐两次水果，根据老人身体情况提供正常餐、流食和碎食，免费送入老人的房间。</p>','[\"park/migration/2026/08/08/pk00020_cat_139.png\"]',NULL,5,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(40,'PK00020','payment_way','缴费方式','<p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">1、床位费：2000元/月起</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">2、护理费：800元/月起</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">3、餐费：1000元/月</span></p>',NULL,NULL,6,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(41,'PK00019','live_env','居住环境','<p>1.本院位于宝山区吴淞街道，与炮台湾湿地公园一墙之隔，上海本地俗称吴淞口，北窗俯瞰吴淞炮台湾湿地森林公园千尺绿地、南窗眺望黄浦江和长江汇流趋海。</p><p>2.本院前身为海军部队宾馆改建，风景优美，绿化率高，室外活动空间大，空气清醒，安静舒适。</p><p>3.本院装修参照养老机构适老化改造要求，除外部绿化地带，为一栋8层高的建筑，设有4部电梯；公共区域也设置无障碍设施，一切要求从老人的安全居住为主。</p>','[\"park/migration/2026/08/08/pk00019_env_141.png\", \"park/migration/2026/08/08/pk00019_env_142.png\", \"park/migration/2026/08/08/pk00019_env_143.png\", \"park/migration/2026/08/08/pk00019_env_144.png\", \"park/migration/2026/08/08/pk00019_env_145.png\"]',NULL,4,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(42,'PK00019','catering','餐饮服务','<p>本院餐厅可以容纳160-200位老人同时用餐，中度护理以上老人可以选择送餐进房；专业营养师制订菜谱，每周一更新，分为无糖餐和普通餐，对痛风等忌口病症也区别对待。对需要调剂口味的老人，我们推出的小锅菜也很受欢迎。保证老人吃的营养又健康。</p>','[\"park/migration/2026/08/08/pk00019_cat_146.png\"]',NULL,5,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(43,'PK00019','payment_way','缴费方式','<p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">1、床位费：2100-7800元/月</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">2、护理费：990-8000元/月</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">3、餐费：900元/月</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">4、医疗保证金：10000元（离院时7个工作日内退回）</span></p>',NULL,NULL,6,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(44,'PK00018','live_env','居住环境','<p>星辰家将周边自然环境与适老化设计完美融合，致力于为广大老年人提供绿色、生态、舒适的养老环境。</p><p>让养老院远离喧嚣融入大自然，让老人望得见山，看得见水，记得住乡愁。</p><p>让我们尊贵的客户沉浸于绿意盎然的环境中。</p>','[\"park/migration/2026/08/08/pk00018_env_147.png\", \"park/migration/2026/08/08/pk00018_env_148.png\", \"park/migration/2026/08/08/pk00018_env_149.png\", \"park/migration/2026/08/08/pk00018_env_150.png\", \"park/migration/2026/08/08/pk00018_env_151.png\", \"park/migration/2026/08/08/pk00018_env_152.png\", \"park/migration/2026/08/08/pk00018_env_153.png\", \"park/migration/2026/08/08/pk00018_env_154.png\", \"park/migration/2026/08/08/pk00018_env_155.png\", \"park/migration/2026/08/08/pk00018_env_156.png\", \"park/migration/2026/08/08/pk00018_env_157.png\", \"park/migration/2026/08/08/pk00018_env_158.png\"]',NULL,4,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(45,'PK00018','payment_way','缴费方式','<p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">1、床位费：1768-6120元/人/月</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">2、护理费：1500-3300元/人/月</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">3、餐费：1200元/人/月</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">4、押金：本地老人 10000元/人，异地老人 40000元/人</span></p>',NULL,NULL,6,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(46,'PK00010','live_env','居住环境','与北京副中心咫尺之隔，四河交汇，生态宜人，交通便利。日常可乘坐大爱班车、209公交抵达北京市区及香河城区，生活便捷。','[\"park/migration/2026/08/08/pk00010_env_161.png\", \"park/migration/2026/08/08/pk00010_env_162.png\", \"park/migration/2026/08/08/pk00010_env_163.png\", \"park/migration/2026/08/08/pk00010_env_164.png\", \"park/migration/2026/08/08/pk00010_env_165.png\", \"park/migration/2026/08/08/pk00010_env_166.png\", \"park/migration/2026/08/08/pk00010_env_167.png\", \"park/migration/2026/08/08/pk00010_env_168.png\", \"park/migration/2026/08/08/pk00010_env_169.png\"]',NULL,4,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(47,'PK00010','catering','餐饮服务','自然农场，规划六大主题乐园，实现观光耕种、采摘果蔬等悠然生活，同时时令果蔬食材专供，专属餐厅配置，专业厨师烹饪，遵循“膳食营养平衡”标准，定制适老化膳食，让长者获得身心双重滋养。','[\"park/migration/2026/08/08/pk00010_cat_170.png\", \"park/migration/2026/08/08/pk00010_cat_171.png\"]',NULL,5,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(48,'PK00010','payment_way','缴费方式','<p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\"><strong>1、租赁型产品：</strong></span><span style=\"font-size: 14px;\">租赁费用+押金+月费+餐费+能源费+增值服务费</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\"><strong>2、旅居产品：</strong></span><span style=\"font-size: 14px;\">旅居消费卡趸交+押金+餐费+增值服务费</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\"><strong>3、长期权益型：</strong></span><span style=\"font-size: 14px;\">月费3800元/月起</span></p>',NULL,NULL,6,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(49,'PK00005','live_env','居住环境','院内拥有独立花园，配套专业护理床位，均配有一键紧急呼叫功能','[\"park/migration/2026/08/08/pk00005_env_172.png\"]',NULL,4,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(50,'PK00011','live_env','居住环境','坐落五指山国家热带雨林核心区域，位于五指山市西南方向，三面雨林一面城，闹中取静。世界级热带雨林，每立方厘米负氧离子含量高达20000个以上。','[\"park/migration/2026/08/08/pk00011_env_181.png\", \"park/migration/2026/08/08/pk00011_env_182.png\", \"park/migration/2026/08/08/pk00011_env_183.png\", \"park/migration/2026/08/08/pk00011_env_184.png\", \"park/migration/2026/08/08/pk00011_env_185.png\", \"park/migration/2026/08/08/pk00011_env_186.png\", \"park/migration/2026/08/08/pk00011_env_187.png\", \"park/migration/2026/08/08/pk00011_env_188.png\", \"park/migration/2026/08/08/pk00011_env_189.png\"]',NULL,4,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(51,'PK00011','catering','餐饮服务','自有农场提供有机食材，三餐均是自助餐，营养搭配齐全。','[\"park/migration/2026/08/08/pk00011_cat_190.png\", \"park/migration/2026/08/08/pk00011_cat_191.png\", \"park/migration/2026/08/08/pk00011_cat_192.png\", \"park/migration/2026/08/08/pk00011_cat_193.png\", \"park/migration/2026/08/08/pk00011_cat_194.png\", \"park/migration/2026/08/08/pk00011_cat_195.png\", \"park/migration/2026/08/08/pk00011_cat_196.png\", \"park/migration/2026/08/08/pk00011_cat_197.png\"]',NULL,5,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(52,'PK00011','payment_way','缴费方式','<p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">1、整体费用：最低499元三天两晚，最高108万120个月入住权</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">2、房间月费：9600元单人含吃住，12000元双人含吃住</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">3、餐费：会员餐费人均80元/天，散客早餐28元、中餐48元、晚餐40元，三餐均是自助餐</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">备注：无押金，刷卡或异地转账均可，办理入住后如出现退卡需扣除卡费30%的违约金，额外实际入住天数按对应的产品套餐使用情况扣除</span></p>',NULL,NULL,6,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(53,'PK00014','live_env','居住环境','<p>柳州东城海阳颐养中心由A座和B座两栋建筑体组成，设置连廊贯通，让长者生活居住体验舒适便捷。A座为7层，B座为6层，一层为办公和文娱活动区域，二至七层为长者照料单元。其中，A座一层主要为接待大厅及办公区、会议室，同时配套设计适老化厨房及餐厅;B座一层则配置长者多元化娱乐空间，如棋牌室、书画室、阅览室、电脑室、多功能活动室、洗衣房等。每层均配套设有餐厅兼活动室、备餐间、家属探视间、护理站、药存间、清洁间、污物存放室间、卫生间等用房，以及户外活动场地及空中花园，同时屋顶设有晾晒区。</p>','[\"park/migration/2026/08/08/pk00014_env_199.png\", \"park/migration/2026/08/08/pk00014_env_200.png\", \"park/migration/2026/08/08/pk00014_env_201.png\", \"park/migration/2026/08/08/pk00014_env_202.png\", \"park/migration/2026/08/08/pk00014_env_203.png\", \"park/migration/2026/08/08/pk00014_env_204.png\"]',NULL,4,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(54,'PK00014','catering','餐饮服务','<p>配套设计适老化厨房及餐厅</p>','[\"park/migration/2026/08/08/pk00014_cat_205.png\"]',NULL,5,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(55,'PK00014','payment_way','缴费方式','<p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">1、床位费：1700元/床/月</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">2、餐费：1000元/人/月，</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">3、护理费：3435-3635元/人/月</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">入住优惠方案：三个月送一周，一年送一个月</span></p>',NULL,NULL,6,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(56,'PK00017','live_env','居住环境','<p>侨辉天颐康养城位于嘉定区南翔镇板块，南翔镇是上海市四大历史名镇之一，素有“小小南翔赛苏城”的美誉。而本次2035规划更是将南翔建设成为小而美的特色综合性城镇——小美南翔。围绕城市、产业、生态三个方面，重点打造小而优美、精致宜人的城市空间；小而精美、智创引领的产业空间；小而恬美、宁静致远的生态空间。</p>','[\"park/migration/2026/08/08/pk00017_env_210.png\", \"park/migration/2026/08/08/pk00017_env_211.png\", \"park/migration/2026/08/08/pk00017_env_212.png\", \"park/migration/2026/08/08/pk00017_env_213.png\", \"park/migration/2026/08/08/pk00017_env_214.png\", \"park/migration/2026/08/08/pk00017_env_215.png\", \"park/migration/2026/08/08/pk00017_env_216.png\", \"park/migration/2026/08/08/pk00017_env_217.png\", \"park/migration/2026/08/08/pk00017_env_218.png\", \"park/migration/2026/08/08/pk00017_env_219.png\", \"park/migration/2026/08/08/pk00017_env_220.png\", \"park/migration/2026/08/08/pk00017_env_221.png\", \"park/migration/2026/08/08/pk00017_env_222.png\", \"park/migration/2026/08/08/pk00017_env_223.png\", \"park/migration/2026/08/08/pk00017_env_224.png\", \"park/migration/2026/08/08/pk00017_env_225.png\", \"park/migration/2026/08/08/pk00017_env_226.png\", \"park/migration/2026/08/08/pk00017_env_227.png\", \"park/migration/2026/08/08/pk00017_env_228.png\"]',NULL,4,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(57,'PK00017','catering','餐饮服务','<p>餐厅食堂每天大概提供20多种菜品，非常的琳琅满目。既有中餐也有西餐，还有专门为糖尿病人提供了专用的出菜窗口。</p>','[\"park/migration/2026/08/08/pk00017_cat_229.png\", \"park/migration/2026/08/08/pk00017_cat_230.png\", \"park/migration/2026/08/08/pk00017_cat_231.png\", \"park/migration/2026/08/08/pk00017_cat_232.png\"]',NULL,5,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(58,'PK00017','payment_way','缴费方式','<p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">1、床位费：3920元/人/月起</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">2、护理费：2430元/人/月起</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">3、餐费：1000-1500元/人/月</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">4、押金：20万/人</span></p>',NULL,NULL,6,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(59,'PK00007','live_env','居住环境','项目7-20层内，每层设置有休息区、就餐区、护士站、处置室及治疗室等配套活动空间。以最大限度满足入住长者需求。同时为长者打造了1000余平米独具匠心的屋顶花园。','[\"park/migration/2026/08/08/pk00007_env_236.png\"]',NULL,4,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(60,'PK00007','catering','餐饮服务','科学合理的营养膳食：老人膳食食谱由专业一级营养师和高级烹饪厨师根据老人饮食特点制定，并不断研发更新。 与中华中医药学会合作，开发特色适老养生餐饮。 食品源头保障，三餐一点，每日新鲜食材供应超过30种，七大营养齐全，比例事宜；粗粮搭配，荤素搭配，干稀搭配。家庭厨房设计，精心为您准备家庭聚会的空间，品尝家的味道。 严格的食品48小时留样制度。','[\"park/migration/2026/08/08/pk00007_cat_237.png\", \"park/migration/2026/08/08/pk00007_cat_238.png\", \"park/migration/2026/08/08/pk00007_cat_239.png\"]',NULL,5,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(61,'PK00007','payment_way','缴费方式','床位费+护理服务费',NULL,NULL,6,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(62,'PK00009','catering','餐饮服务','专业营养师和星级厨师为长者提供科学配餐，保障营养均衡，延缓衰老；制定特色风味餐食，满足长者个性化需求。专业营养评估服务、科学配餐，保障营养均衡，延缓衰老；特色风味餐食，满足长者个性化需求；为长者提供基本膳食、低脂餐、糖尿病餐等治疗膳。还可提供养生膳食、流食、半流食等特殊餐品。建设老年医学学会食品营养科教实践基地，建立系统的老年营养风险管控体系，保障长者营养健康。','[\"park/migration/2026/08/08/pk00009_cat_241.png\"]',NULL,5,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(63,'PK00009','payment_way','缴费方式','<p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">1、房间费用：</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">D卡（1年）：3400-15000元/月</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">A卡（长期）：130-350万元/房</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">2、养老服务费用：1200-11800元/月/人</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">3、营养餐费用：1800元/月/人，自助营养餐，刷卡结算（早餐15元，午餐30元，晚餐15元）</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">备注：1、医疗保证金：每位会员入住需缴纳医疗保证金5万元/人</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\"> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;2、会员入住需养老公寓进行身体状况评估，确定服务级别</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\"> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;3、营养餐为充值刷卡及时结算，会员可自由选择</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\"> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;4、养老费用构成：居所费用+养老服务费（按月计费需全年缴纳）</span></p>',NULL,NULL,6,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(64,'PK00006','live_env','居住环境','悦年华·颐养中心（北京瀛海）采用独立庭院设计规划，围合式静谧庭院，规划小组团绿植景观与适老化户外设施，在保证长者安全的同时，营造闲适的颐养氛围。充分满足长者的户外休憩与活动需求。','[\"park/migration/2026/08/08/pk00006_env_242.png\", \"park/migration/2026/08/08/pk00006_env_243.png\", \"park/migration/2026/08/08/pk00006_env_244.png\"]',NULL,4,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(65,'PK00006','catering','餐饮服务','<p>悦年华·颐养中心（北京瀛海）专业营养师制定营养食谱，资深厨师团队研制适老化菜品，确保安全营养的同时，兼顾口感，让长者的每一餐不止放心，更能享受多种美味。专业团队精选安全食材，根据长者健康状况，提供易于咀嚼和消化的流质、半流质食物，同时为患有高血压、糖尿病、痛风等慢性病或有饮食禁忌的长者提供定制化膳食。从高品质饮食开始，维护长者身体健康。</p><p>悦年华·颐养中心（北京瀛海）与多家有机农场和众多原产地品牌进行合作，保证全程可溯源，做到严格筛选，让长者吃的更健康。</p>',NULL,NULL,5,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(66,'PK00006','payment_way','缴费方式','<p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">1、房间月费：5365-8048元</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">2、护理费用：1200-15000元/月</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">3、餐费：1500元/人/月，按日计费</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">4、押金：本地老人10万元/人，夫妻两人同住为2人15万元；异地老人10万元/人，夫妻两人同住为2人15万元</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">5、一次性安置费：1200元/人</span></p>',NULL,NULL,6,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(67,'PK00013','live_env','居住环境','<p>园区景观以“善意”为核心诉求，以“适老化”为设计标准，专为长者而设计五园八境，即放松-闻莺花园、休闲-落弈花园、娱乐-探趣花园、康养-长椿花园、康复-风采花园五重活动花园与情、香、品、艺、文、智、悦、雅八重宅间境界，打造出了无微不至的景观体验感。</p>','[\"park/migration/2026/08/08/pk00013_env_249.png\", \"park/migration/2026/08/08/pk00013_env_250.png\", \"park/migration/2026/08/08/pk00013_env_251.png\", \"park/migration/2026/08/08/pk00013_env_252.png\", \"park/migration/2026/08/08/pk00013_env_253.png\", \"park/migration/2026/08/08/pk00013_env_254.png\", \"park/migration/2026/08/08/pk00013_env_255.png\", \"park/migration/2026/08/08/pk00013_env_256.png\", \"park/migration/2026/08/08/pk00013_env_257.png\"]',NULL,4,1,'2026-08-09 10:10:30','2026-08-09 10:10:30','system','system',0,NULL),(68,'PK00013','catering','餐饮服务','<p>两大主题餐厅，膳食特配，提供套餐、自助餐、半自助餐、零点、适老化餐、家庭厨房、包间、送餐服务等</p>','[\"park/migration/2026/08/08/pk00013_cat_258.png\", \"park/migration/2026/08/08/pk00013_cat_259.png\", \"park/migration/2026/08/08/pk00013_cat_260.png\", \"park/migration/2026/08/08/pk00013_cat_261.png\"]',NULL,5,1,'2026-08-09 10:10:31','2026-08-09 10:10:31','system','system',0,NULL),(69,'PK00012','live_env','居住环境','<p>便利出行：项目位于大托铺街道大托村支部，毗邻公交站大托村站，距长沙绕城高速车程约6公里，距地铁1号线车程约7公里，交通便利。</p><p>醇熟配套：内设超市及药房，可满足院内日常需求，约5公里可抵达环宇城、友阿奥特莱斯等购物中心，毗邻湘江，空气宜人，环境清幽，景色如画，予以长者安静、舒心的居住环境。</p><p>健康医疗：毗邻中南大学湘雅二医院、湖南省荣军医院、湖南省人民政府机关医院，医疗资源丰富。内部配有全科医生、护士，拟设置化验科、B超、心电图检查室、药房，可在一定程度上满足长者康复及老年慢性病的管理和健康监测的需求。</p>','[\"park/migration/2026/08/08/pk00012_env_268.png\", \"park/migration/2026/08/08/pk00012_env_269.png\", \"park/migration/2026/08/08/pk00012_env_270.png\", \"park/migration/2026/08/08/pk00012_env_271.png\", \"park/migration/2026/08/08/pk00012_env_272.png\"]',NULL,4,1,'2026-08-09 10:10:31','2026-08-09 10:10:31','system','system',0,NULL),(70,'PK00012','catering','餐饮服务','<p>科学配比营养膳食，予以生活贴心照料。项目提供专业营养膳食体系指导，保障长者饮食健康均衡</p><p>1、提供分餐食用，按照老年人生活习惯进行每周食谱制定</p><p>2、每周膳食由专业营养师根据季节变化、依据时令制定</p><p>3、为生命晚期或吞咽困难的长者专研符合营养膳食标准的特殊饮食</p>','[\"park/migration/2026/08/08/pk00012_cat_273.png\", \"park/migration/2026/08/08/pk00012_cat_274.png\", \"park/migration/2026/08/08/pk00012_cat_275.png\", \"park/migration/2026/08/08/pk00012_cat_276.png\", \"park/migration/2026/08/08/pk00012_cat_277.png\", \"park/migration/2026/08/08/pk00012_cat_278.png\"]',NULL,5,1,'2026-08-09 10:10:31','2026-08-09 10:10:31','system','system',0,NULL),(71,'PK00012','payment_way','缴费方式','<p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">1、整体费用3000-8300元/月/人</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">2、本地以及外地老人押金均为8000元/人</span></p>',NULL,NULL,6,1,'2026-08-09 10:10:31','2026-08-09 10:10:31','system','system',0,NULL),(72,'PK00008','live_env','居住环境','康宁津园大型养老综合体坐落于天津市团泊湖西区-天津健康产业园内。团泊湖是距离天津市区最近的自然生态保护区，距离市区仅10公里，拥有51平方公里湖面积，相当于10个杭州西湖，8个东丽湖，曾被联合国定为野生珍禽保护区，是天津唯一一个鸟类自然生态保护区，而且具有丰富的温泉地热资源，空气质量在天津区域内属一级。','[\"park/migration/2026/08/08/pk00008_env_285.png\", \"park/migration/2026/08/08/pk00008_env_286.png\", \"park/migration/2026/08/08/pk00008_env_287.png\", \"park/migration/2026/08/08/pk00008_env_288.png\"]',NULL,4,1,'2026-08-09 10:10:31','2026-08-09 10:10:31','system','system',0,NULL),(73,'PK00008','catering','餐饮服务','<p>康宁津园内建有中央厨房，建筑面积3800平米。同时园区内配建有三个幸福食堂，建筑面积1000平米左右，可保障园区内约5000余位会员日常就餐。</p><p>首先菜单设计从营养健康入手，以定时定量，合理营养为原则，提前公布菜单给老人，并详细介绍每种菜品的营养成分，合理搭配的理念。为会员设计制定多套内容丰富的营养菜单，保证会员每日摄取均衡的营养。</p>','[\"park/migration/2026/08/08/pk00008_cat_289.png\", \"park/migration/2026/08/08/pk00008_cat_290.png\", \"park/migration/2026/08/08/pk00008_cat_291.png\", \"park/migration/2026/08/08/pk00008_cat_292.png\", \"park/migration/2026/08/08/pk00008_cat_293.png\", \"park/migration/2026/08/08/pk00008_cat_294.png\"]',NULL,5,1,'2026-08-09 10:10:31','2026-08-09 10:10:31','system','system',0,NULL),(74,'PK00008','payment_way','缴费方式','<p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\"><strong>月费型产品</strong></span><span style=\"font-size: 14px;\">：</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">1、综合月费：1人入住6958元起，2人入住9818元起</span></p><p style=\"text-indent: 2em;\"><span style=\"font-size: 14px;\">2、紧急备用金：5万/户</span></p>',NULL,NULL,6,1,'2026-08-09 10:10:31','2026-08-09 10:10:31','system','system',0,NULL),(75,'PK00016','live_env','居住环境','<p>项目位于上海市浦东新区六奉公路与沪南路交叉口，毗邻新场古镇与16号地铁站，地理位置优越。距迪士尼度假区，距离交通枢纽人口密集的龙阳路均驱车30分钟，距离浦东机场驱车30分钟。</p>','[\"park/migration/2026/08/08/pk00016_env_295.png\", \"park/migration/2026/08/08/pk00016_env_296.png\", \"park/migration/2026/08/08/pk00016_env_297.png\", \"park/migration/2026/08/08/pk00016_env_298.png\", \"park/migration/2026/08/08/pk00016_env_299.png\"]',NULL,4,1,'2026-08-09 10:10:31','2026-08-09 10:10:31','system','system',0,NULL),(76,'PK00003','live_env','居住环境','5000平米中心庭院，绿植种类丰富，景观轴部分绿化率可达到70%。年轮广场、锦鲤池、承诺之环、景观轩中移步易景，在环形健康步道中散步，在鸟语花香的环境之中，让心情更愉快，身体更健康','[\"park/migration/2026/08/08/pk00003_env_302.png\", \"park/migration/2026/08/08/pk00003_env_303.png\", \"park/migration/2026/08/08/pk00003_env_304.png\", \"park/migration/2026/08/08/pk00003_env_305.png\", \"park/migration/2026/08/08/pk00003_env_306.png\", \"park/migration/2026/08/08/pk00003_env_307.png\", \"park/migration/2026/08/08/pk00003_env_308.png\", \"park/migration/2026/08/08/pk00003_env_309.png\"]',NULL,4,1,'2026-08-09 10:10:31','2026-08-09 10:10:31','system','system',0,NULL),(77,'PK00003','catering','餐饮服务','一天至少25个菜品，30多种食材营养搭配更加均衡，自助餐厅、零点餐厅、茶室、咖啡厅可以选择，鲁菜川菜粤菜等各地名菜，多元化口味满足味蕾，自己选择最喜欢的口味','[\"park/migration/2026/08/08/pk00003_cat_310.png\", \"park/migration/2026/08/08/pk00003_cat_311.png\"]',NULL,5,1,'2026-08-09 10:10:31','2026-08-09 10:10:31','system','system',0,NULL),(78,'PK00003','payment_way','缴费方式','<p style=\"text-indent: 2em;\"><br></p>',NULL,NULL,6,1,'2026-08-09 10:10:31','2026-08-09 10:10:31','system','system',0,NULL),(79,'PK00004','catering','餐饮服务','九华山庄贵宾楼酒店拥有一家中式餐厅，一家西餐厅及一家风味餐厅。主打餐厅粤王食府，取粤菜以我为王之意，餐厅环境优雅，明亮的落地窗外雾气袅袅的温泉水若隐若现，给予宾客别样的就餐体验。所有美食由香港资深名厨主理，多款独创菜品，融汇中西，呈现独一无二的味觉盛宴。','[\"park/migration/2026/08/08/pk00004_cat_314.png\", \"park/migration/2026/08/08/pk00004_cat_315.png\"]',NULL,5,1,'2026-08-09 10:10:31','2026-08-09 10:10:31','system','system',0,NULL);
