DROP TABLE IF EXISTS `park_facility_type`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `park_facility_type` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `park_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '机构编码',
  `facility_type_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设施类型编码',
  `facility_type_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设施类型名称（如"健身房"、"棋牌室"、"医疗室"、"阅览室"）',
  `facility_type_category` tinyint NOT NULL DEFAULT '1' COMMENT '设施类别（1=休闲娱乐, 2=医疗健康, 3=运动健身, 4=文化教育, 5=生活服务, 6=安全保障）',
  `building_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所在楼栋（如"A栋"、"南楼"）',
  `floor` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所在楼层',
  `area` decimal(8,2) DEFAULT NULL COMMENT '面积（平方米）',
  `capacity` int DEFAULT NULL COMMENT '最大容纳人数',
  `open_time` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '开放时间（如"08:00-20:00"）',
  `facility_type_description` text COLLATE utf8mb4_unicode_ci COMMENT '设施详细描述',
  `cover_image` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面图URL',
  `images` text COLLATE utf8mb4_unicode_ci COMMENT '设施图片URL列表（JSON数组）',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序号',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态（0=停用, 1=启用）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_facility_code` (`park_code`,`facility_type_code`),
  KEY `idx_park_code` (`park_code`),
  KEY `idx_facility_category` (`facility_type_category`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='机构配套设施';
/*!40101 SET character_set_client = @saved_cs_client */;

