DROP TABLE IF EXISTS `park_food_type`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `park_food_type` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `park_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '机构编码',
  `food_type_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '餐饮类型编码',
  `food_type_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '餐饮类型名称（如"普通餐"、"营养餐"、"糖尿病餐"）',
  `meal_plan` tinyint NOT NULL DEFAULT '1' COMMENT '餐饮方案（1=三餐, 2=三餐两点, 3=三餐三点, 4=自选）',
  `diet_features` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '饮食特色（JSON数组）',
  `sample_menu` text COLLATE utf8mb4_unicode_ci COMMENT '示例菜单（JSON格式）',
  `special_diet` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否支持特殊饮食（0=否, 1=是）',
  `special_diet_description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '特殊饮食说明',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '详细描述',
  `cover_image` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面图URL',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序号',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态（0=停售, 1=在售）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_food_type_code` (`park_code`,`food_type_code`),
  KEY `idx_park_code` (`park_code`),
  KEY `idx_meal_plan` (`meal_plan`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='养老机构餐饮类型';
