LOCK TABLES `park_food_type` WRITE;
/*!40000 ALTER TABLE `park_food_type` DISABLE KEYS */;
INSERT INTO `park_food_type` VALUES (1,'PK00002','FT-PK02-001','普通膳食',1,NULL,NULL,0,NULL,NULL,NULL,0,1,'2026-08-06 09:17:55','2026-08-06 09:17:55','AC00001','AC00001',0,NULL),(2,'PK00020','PK00020FT01','营养膳食',1,NULL,NULL,0,NULL,'<p>提供三次正餐两次水果，根据老人身体情况提供正常餐、流食和碎食，免费送入老人的房间。</p>','park/migration/2026/08/08/pk00020_food_135.png',1,1,'2026-08-09 10:10:29','2026-08-09 10:10:29','system','system',0,NULL),(3,'PK00019','PK00019FT01','营养膳食',1,NULL,NULL,0,NULL,'<p>本院餐厅可以容纳160-200位老人同时用餐，中度护理以上老人可以选择送餐进房；专业营养师制订菜谱，每周一更新，分为无糖餐和普通餐，对痛风等忌口病症也区别对待。对需要调剂口味的老人，我们推出的小锅菜也很受欢迎。保证老人吃的营养又健康。</p>','park/migration/2026/08/08/pk00019_food_140.png',1,1,'2026-08-09 10:10:29','2026-08-09 10:10:29','system','system',0,NULL),(4,'PK00010','PK00010FT01','营养膳食',1,NULL,NULL,0,NULL,'自然农场，规划六大主题乐园，实现观光耕种、采摘果蔬等悠然生活，同时时令果蔬食材专供，专属餐厅配置，专业厨师烹饪，遵循“膳食营养平衡”标准，定制适老化膳食，让长者获得身心双重滋养。','park/migration/2026/08/08/pk00010_food_159.png',1,1,'2026-08-09 10:10:29','2026-08-09 10:10:29','system','system',0,NULL),(5,'PK00011','PK00011FT01','营养膳食',1,NULL,NULL,0,NULL,'自有农场提供有机食材，三餐均是自助餐，营养搭配齐全。','park/migration/2026/08/08/pk00011_food_173.png',1,1,'2026-08-09 10:10:29','2026-08-09 10:10:29','system','system',0,NULL),(6,'PK00014','PK00014FT01','营养膳食',1,NULL,NULL,0,NULL,'<p>配套设计适老化厨房及餐厅</p>','park/migration/2026/08/08/pk00014_food_198.png',1,1,'2026-08-09 10:10:29','2026-08-09 10:10:29','system','system',0,NULL),(7,'PK00017','PK00017FT01','营养膳食',1,NULL,NULL,0,NULL,'<p>餐厅食堂每天大概提供20多种菜品，非常的琳琅满目。既有中餐也有西餐，还有专门为糖尿病人提供了专用的出菜窗口。</p>','park/migration/2026/08/08/pk00017_food_206.png',1,1,'2026-08-09 10:10:29','2026-08-09 10:10:29','system','system',0,NULL),(8,'PK00007','PK00007FT01','营养膳食',1,NULL,NULL,0,NULL,'科学合理的营养膳食：老人膳食食谱由专业一级营养师和高级烹饪厨师根据老人饮食特点制定，并不断研发更新。 与中华中医药学会合作，开发特色适老养生餐饮。 食品源头保障，三餐一点，每日新鲜食材供应超过30种，七大营养齐全，比例事宜；粗粮搭配，荤素搭配，干稀搭配。家庭厨房设计，精心为您准备家庭聚会的空间，品尝家的味道。 严格的食品48小时留样制度。','park/migration/2026/08/08/pk00007_food_233.png',1,1,'2026-08-09 10:10:29','2026-08-09 10:10:29','system','system',0,NULL),(9,'PK00009','PK00009FT01','营养膳食',1,NULL,NULL,0,NULL,'专业营养师和星级厨师为长者提供科学配餐，保障营养均衡，延缓衰老；制定特色风味餐食，满足长者个性化需求。专业营养评估服务、科学配餐，保障营养均衡，延缓衰老；特色风味餐食，满足长者个性化需求；为长者提供基本膳食、低脂餐、糖尿病餐等治疗膳。还可提供养生膳食、流食、半流食等特殊餐品。建设老年医学学会食品营养科教实践基地，建立系统的老年营养风险管控体系，保障长者营养健康。','park/migration/2026/08/08/pk00009_food_240.png',1,1,'2026-08-09 10:10:29','2026-08-09 10:10:29','system','system',0,NULL),(10,'PK00006','PK00006FT01','营养膳食',1,NULL,NULL,0,NULL,'<p>悦年华·颐养中心（北京瀛海）专业营养师制定营养食谱，资深厨师团队研制适老化菜品，确保安全营养的同时，兼顾口感，让长者的每一餐不止放心，更能享受多种美味。专业团队精选安全食材，根据长者健康状况，提供易于咀嚼和消化的流质、半流质食物，同时为患有高血压、糖尿病、痛风等慢性病或有饮食禁忌的长者提供定制化膳食。从高品质饮食开始，维护长者身体健康。</p><p>悦年华·颐养中心（北京瀛海）与多家有机农场和众多原产地品牌进行合作，保证全程可溯源，做到严格筛选，让长者吃的更健康。</p>',NULL,1,1,'2026-08-09 10:10:29','2026-08-09 10:10:29','system','system',0,NULL),(11,'PK00013','PK00013FT01','营养膳食',1,NULL,NULL,0,NULL,'<p>两大主题餐厅，膳食特配，提供套餐、自助餐、半自助餐、零点、适老化餐、家庭厨房、包间、送餐服务等</p>','park/migration/2026/08/08/pk00013_food_245.png',1,1,'2026-08-09 10:10:29','2026-08-09 10:10:29','system','system',0,NULL),(12,'PK00012','PK00012FT01','营养膳食',1,NULL,NULL,0,NULL,'<p>科学配比营养膳食，予以生活贴心照料。项目提供专业营养膳食体系指导，保障长者饮食健康均衡</p><p>1、提供分餐食用，按照老年人生活习惯进行每周食谱制定</p><p>2、每周膳食由专业营养师根据季节变化、依据时令制定</p><p>3、为生命晚期或吞咽困难的长者专研符合营养膳食标准的特殊饮食</p>','park/migration/2026/08/08/pk00012_food_262.png',1,1,'2026-08-09 10:10:29','2026-08-09 10:10:29','system','system',0,NULL),(13,'PK00008','PK00008FT01','营养膳食',1,NULL,NULL,0,NULL,'<p>康宁津园内建有中央厨房，建筑面积3800平米。同时园区内配建有三个幸福食堂，建筑面积1000平米左右，可保障园区内约5000余位会员日常就餐。</p><p>首先菜单设计从营养健康入手，以定时定量，合理营养为原则，提前公布菜单给老人，并详细介绍每种菜品的营养成分，合理搭配的理念。为会员设计制定多套内容丰富的营养菜单，保证会员每日摄取均衡的营养。</p>','park/migration/2026/08/08/pk00008_food_279.png',1,1,'2026-08-09 10:10:29','2026-08-09 10:10:29','system','system',0,NULL),(14,'PK00003','PK00003FT01','营养膳食',1,NULL,NULL,0,NULL,'一天至少25个菜品，30多种食材营养搭配更加均衡，自助餐厅、零点餐厅、茶室、咖啡厅可以选择，鲁菜川菜粤菜等各地名菜，多元化口味满足味蕾，自己选择最喜欢的口味','park/migration/2026/08/08/pk00003_food_300.png',1,1,'2026-08-09 10:10:29','2026-08-09 10:10:29','system','system',0,NULL),(15,'PK00004','PK00004FT01','营养膳食',1,NULL,NULL,0,NULL,'九华山庄贵宾楼酒店拥有一家中式餐厅，一家西餐厅及一家风味餐厅。主打餐厅粤王食府，取粤菜以我为王之意，餐厅环境优雅，明亮的落地窗外雾气袅袅的温泉水若隐若现，给予宾客别样的就餐体验。所有美食由香港资深名厨主理，多款独创菜品，融汇中西，呈现独一无二的味觉盛宴。','park/migration/2026/08/08/pk00004_food_312.png',1,1,'2026-08-09 10:10:29','2026-08-09 10:10:29','system','system',0,NULL);
/*!40000 ALTER TABLE `park_food_type` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `park_info`
--

DROP TABLE IF EXISTS `park_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `park_info` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `park_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '机构唯一编码',
  `full_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '机构名称',
  `short_name` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '机构简称',
  `supplier_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属供应商编码',
  `brand` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '品牌名称',
  `brand_introduction` text COLLATE utf8mb4_unicode_ci COMMENT '品牌简介',
  `brand_logo` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '品牌Logo',
  `operation_subject` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '运营主体',
  `operation_subject_description` text COLLATE utf8mb4_unicode_ci COMMENT '运营主体介绍',
  `important_shareholders` text COLLATE utf8mb4_unicode_ci COMMENT '重要股东',
  `partner_company` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合作公司主体',
  `business_license_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '营业执照号',
  `business_bd` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商务BD',
  `ability_type` tinyint DEFAULT NULL COMMENT '机构类型（1=持续照料社区CCRC, 2=综合性养老院, 3=养老公寓CB, 4=认知症照护机构, 5=社区嵌入式照料中心CC, 6=居家照护HC, 7=护理院NH, 8=活力长者社区AC, 9=敬老院）',
  `ability_type_description` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '机构类型描述',
  `network_tags` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '网络标签（逗号分隔：vital=活力长居,care=照护长居,sojourn=旅居养老）',
  `vital_config` text COLLATE utf8mb4_unicode_ci COMMENT '活力长居展示配置JSON（banners+thumbnail）',
  `care_config` text COLLATE utf8mb4_unicode_ci COMMENT '照护长居展示配置JSON（banners+thumbnail）',
  `sojourn_config` text COLLATE utf8mb4_unicode_ci COMMENT '旅居展示配置JSON（banners+thumbnail）',
  `nature_type` tinyint DEFAULT NULL COMMENT '机构性质（1=公办, 2=民办, 3=险资背景, 4=集团旗下, 5=房产旗下, 6=公办民营）',
  `nature_type_description` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '机构性质描述',
  `specialty_tag` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '特色标签（多个逗号隔开）',
  `dayan_level` tinyint DEFAULT NULL COMMENT '评级（1=S, 2=A, 3=B, 4=C, 5=D, 6=E）',
  `province` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '省',
  `province_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '省编码',
  `city` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '城市',
  `city_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '城市编码',
  `district` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '区',
  `district_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '区编码',
  `address` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '具体地址',
  `longitude` decimal(10,6) DEFAULT NULL COMMENT 'ç»åº¦',
  `latitude` decimal(10,6) DEFAULT NULL COMMENT 'çº¬åº¦',
  `service_hotline` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客服电话',
  `base_description` text COLLATE utf8mb4_unicode_ci COMMENT '机构介绍',
  `specialty_description` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '机构特色',
  `total_area` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '占地面积',
  `building_area` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '建筑面积',
  `green_area_rate` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '绿化率',
  `total_beds` int DEFAULT NULL COMMENT '总床位数',
  `available_beds` int DEFAULT NULL COMMENT '可用床位数',
  `occupancy_rate` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '已入住率',
  `staff_count` int DEFAULT NULL COMMENT '员工总数',
  `nurse_count` int DEFAULT NULL COMMENT '护理人员数',
  `nurse_patient_ratio` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '护患比（如1:5）',
  `min_price_display` int DEFAULT NULL COMMENT '最低月费（元）',
  `max_price_display` int DEFAULT NULL COMMENT '最高月费（元）',
  `price_unit` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '价格单位',
  `check_in_age_min` int DEFAULT NULL COMMENT '入住最低年龄',
  `check_in_age_max` int DEFAULT NULL COMMENT '入住最高年龄',
  `check_in_description` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '入住说明',
  `deposit_amount` decimal(12,2) DEFAULT NULL COMMENT '押金金额',
  `deposit_description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '押金说明',
  `contract_period` tinyint DEFAULT NULL COMMENT '合同期限（1=月签, 2=季签, 3=半年, 4=年签）',
  `sort_order` int DEFAULT '0' COMMENT '排序号',
  `is_hot` tinyint DEFAULT NULL COMMENT '平台内评级（1=付费广告, 2=热门）',
  `sub_script` varchar(11) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首页角标（1=最新, 2=最热, 3=优惠, 4=店庆）',
  `operate_status` tinyint(1) DEFAULT NULL COMMENT '运营状态（0=待审核, 1=已上线, 2=已下架, 3=暂停营业；PARK_SM 驱动）',
  `opening_time` datetime DEFAULT NULL COMMENT '开业时间',
  `online_time` datetime DEFAULT NULL COMMENT '上架时间',
  `offline_time` datetime DEFAULT NULL COMMENT '下架时间',
  `add_platform_time` datetime DEFAULT NULL COMMENT '加入平台时间',
  `is_published` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否已发布（0=未发布, 1=已发布）',
  `view_count` int NOT NULL DEFAULT '0' COMMENT '浏览次数',
  `collect_count` int NOT NULL DEFAULT '0' COMMENT '收藏次数',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '数据版本',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_park_code` (`park_code`),
  KEY `idx_full_name` (`full_name`(50)),
  KEY `idx_province_code` (`province_code`),
  KEY `idx_city_code` (`city_code`),
  KEY `idx_district_code` (`district_code`),
  KEY `idx_ability_type` (`ability_type`),
  KEY `idx_nature_type` (`nature_type`),
  KEY `idx_dayan_level` (`dayan_level`),
  KEY `idx_operate_status` (`operate_status`),
  KEY `idx_brand` (`brand`(20)),
  KEY `idx_min_price_display` (`min_price_display`),
  KEY `idx_sort_order` (`sort_order`),
  KEY `idx_is_published` (`is_published`),
  FULLTEXT KEY `ft_full_name` (`full_name`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='养老机构核心信息';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `park_info`
--

