--
-- Table structure for table `park_periphery`
--

DROP TABLE IF EXISTS `park_periphery`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `park_periphery` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `park_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '机构编码',
  `periphery_type` tinyint NOT NULL DEFAULT '1' COMMENT '周边类型（1=交通-公交, 2=交通-地铁, 3=交通-自驾, 4=景点, 5=医疗, 6=购物, 7=公园, 8=其他）',
  `place_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '地点名称',
  `place_address` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '详细地址/路线描述',
  `distance` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '距离描述（如"500米"、"步行10分钟"）',
  `detail_description` text COLLATE utf8mb4_unicode_ci COMMENT '详细描述',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序号',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态（0=隐藏, 1=显示）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
