--
-- Table structure for table `park_pricing`
--

DROP TABLE IF EXISTS `park_pricing`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `park_pricing` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `park_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '机构编码',
  `plan_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '方案名称（如"豪华单人间·月费"）',
  `charge_type` tinyint NOT NULL COMMENT '费类（1=房间费 2=照护费 3=餐费 4=押金 5=设施费 6=服务费 9=其他）',
  `ref_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联类型（room_type/care_type/food_type/facility/service_item/park）',
  `ref_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联编码',
  `ref_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联名称（冗余）',
  `billing_cycle` tinyint DEFAULT NULL COMMENT '计费周期（1=月 2=季 3=半年 4=年 5=一次性）',
  `price_unit` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '自由文本计费单位（设施/服务的 次/小时/场）',
  `original_price` decimal(12,2) DEFAULT NULL COMMENT '原价',
  `sale_price` decimal(12,2) NOT NULL COMMENT '售价',
  `discount_rate` decimal(5,2) DEFAULT NULL COMMENT '折扣率',
  `price_description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '价格说明',
  `includes_items` text COLLATE utf8mb4_unicode_ci COMMENT '包含项目（JSON数组）',
  `effective_date` date NOT NULL COMMENT '生效日期',
  `expire_date` date DEFAULT NULL COMMENT '失效日期（NULL=长期有效）',
  `is_current` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否当前生效价格（0=历史 1=当前）',
  `is_promotion` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否促销价',
  `promotion_description` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '促销说明',
  `price_change_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '价格变更原因',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序号',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态（0=停用 1=启用）',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `current_key` varchar(200) COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when ((`is_current` = 1) and (`deleted` = 0)) then concat(`park_code`,_utf8mb4'|',`charge_type`,_utf8mb4'|',`ref_code`,_utf8mb4'|',coalesce(cast(`billing_cycle` as char charset utf8mb4),_utf8mb4'0')) else NULL end)) STORED COMMENT '当前价唯一键（生成列）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_current` (`current_key`),
  KEY `idx_park_code` (`park_code`),
  KEY `idx_charge_type` (`charge_type`),
  KEY `idx_ref` (`ref_type`,`ref_code`),
  KEY `idx_is_current` (`is_current`),
  KEY `idx_effective_date` (`effective_date`),
  KEY `idx_park_charge` (`park_code`,`charge_type`,`billing_cycle`)
) ENGINE=InnoDB AUTO_INCREMENT=214 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='机构统一定价方案';
/*!40101 SET character_set_client = @saved_cs_client */;

