--
-- Table structure for table `park_pricing_item`
--

DROP TABLE IF EXISTS `park_pricing_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `park_pricing_item` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `pricing_id` bigint NOT NULL COMMENT 'FK→park_pricing.id',
  `park_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '机构编码',
  `item_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联类型（room_type/care_type/food_type/facility/service_item）',
  `item_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联编码',
  `item_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联名称（冗余）',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序号',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  KEY `idx_pricing_id` (`pricing_id`),
  KEY `idx_item` (`park_code`,`item_type`,`item_code`)
) ENGINE=InnoDB AUTO_INCREMENT=211 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='机构定价明细行（套餐关联）';
/*!40101 SET character_set_client = @saved_cs_client */;

