--
-- Table structure for table `park_room_type`
--

DROP TABLE IF EXISTS `park_room_type`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `park_room_type` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `park_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '机构编码',
  `room_type_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '房间类型编码',
  `room_type_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '房间类型名称（如"豪华南向单人间"）',
  `stay_type` tinyint NOT NULL COMMENT '居住类型（1=长居, 2=旅居）',
  `building_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '楼栋名称（如"A栋"、"南楼"）',
  `floor` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所在楼层',
  `room_category` tinyint NOT NULL DEFAULT '1' COMMENT '房间类别（1=单人间, 2=双人间, 3=多人间, 4=套间, 5=VIP房）',
  `area` decimal(8,2) DEFAULT NULL COMMENT '房间面积（平方米）',
  `orientation` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bed_count` int NOT NULL DEFAULT '1' COMMENT '床位数',
  `total_rooms` int NOT NULL DEFAULT '0' COMMENT '该类型房间总数',
  `available_rooms` int NOT NULL DEFAULT '0' COMMENT '可入住数',
  `has_bathroom` tinyint(1) NOT NULL DEFAULT '1' COMMENT '独立卫生间（0=否, 1=是）',
  `has_kitchen` tinyint(1) NOT NULL DEFAULT '0' COMMENT '独立厨房（0=否, 1=是）',
  `has_balcony` tinyint(1) NOT NULL DEFAULT '0' COMMENT '有阳台（0=否, 1=是）',
  `has_tv` tinyint(1) NOT NULL DEFAULT '1' COMMENT '有电视（0=否, 1=是）',
  `has_aircon` tinyint(1) NOT NULL DEFAULT '1' COMMENT '有空调（0=否, 1=是）',
  `has_fridge` tinyint(1) NOT NULL DEFAULT '0' COMMENT '有冰箱（0=否, 1=是）',
  `has_washer` tinyint(1) NOT NULL DEFAULT '0' COMMENT '有洗衣机（0=否, 1=是）',
  `has_wifi` tinyint(1) NOT NULL DEFAULT '1' COMMENT '有WiFi（0=否, 1=是）',
  `has_emergency` tinyint(1) NOT NULL DEFAULT '1' COMMENT '有紧急呼叫（0=否, 1=是）',
  `has_monitor` tinyint(1) NOT NULL DEFAULT '0' COMMENT '有监控（0=否, 1=是）',
  `facilities` text COLLATE utf8mb4_unicode_ci COMMENT '配套设施详情（JSON数组）',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '房间详细说明',
  `cover_image` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面图URL',
  `images` text COLLATE utf8mb4_unicode_ci COMMENT '房间图片URL列表（JSON数组）',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序号',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态（0=停售, 1=在售）',
  `design_description` text COLLATE utf8mb4_unicode_ci COMMENT '户型设计描述',
  `design_image` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '户型图URL',
  `additional_images` text COLLATE utf8mb4_unicode_ci COMMENT '其他户型图片（JSON数组）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_room_type_code` (`park_code`,`room_type_code`),
  KEY `idx_park_code` (`park_code`),
  KEY `idx_stay_type` (`stay_type`),
