CREATE TABLE `service_session` (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `session_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '会话编码',
  `equity_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联权益编码',
  `item_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '服务项目编码（权益激活按 service_item 创建会话时标记）',
  `client_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户编码',
  `butler_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '服务管家编码（待分配时为空）',
  `butler_full_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '服务管家姓名（快照）',
  `service_type` tinyint DEFAULT NULL,
  `service_title` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '服务标题',
  `service_description` text COLLATE utf8mb4_unicode_ci COMMENT '服务描述',
  `priority` tinyint NOT NULL DEFAULT '0' COMMENT '优先级（0=普通, 1=优先, 2=紧急, 3=非常紧急）',
  `source_type` tinyint NOT NULL DEFAULT '1' COMMENT '来源（1=权益触发, 2=客户主动, 3=代理人委托, 4=管家发起）',
  `source_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源编码',
  `park_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联养老机构编码',
  `park_full_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联养老机构名称（快照）',
  `agent_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联代理人编码',
  `channel_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联渠道编码',
  `accept_time` datetime DEFAULT NULL COMMENT '受理时间',
  `complete_time` datetime DEFAULT NULL COMMENT '完成时间',
  `close_time` datetime DEFAULT NULL COMMENT '关闭时间',
  `total_duration` int DEFAULT NULL COMMENT '总服务时长（小时）',
  `touch_count` int NOT NULL DEFAULT '0' COMMENT '服务接触次数',
  `max_use_count` int NOT NULL DEFAULT '1' COMMENT '最大使用次数（激活时从 rel.quantity 快照）',
  `used_count` int NOT NULL DEFAULT '0' COMMENT '已使用次数',
  `quota_type` tinyint(1) NOT NULL DEFAULT '2' COMMENT '配额周期（1=终身,2=年度）',
  `quota_reset_year` int DEFAULT NULL COMMENT '年度配额当前已重置年份（仅 quota_type=2 使用）',
  `is_satisfied` tinyint(1) DEFAULT NULL COMMENT '是否满意（0=否, 1=是）',
  `overall_rating` tinyint(1) DEFAULT NULL COMMENT '综合评分（1-5）',
  `session_status` tinyint NOT NULL DEFAULT '1' COMMENT '会话状态（1=待分配, 2=处理中, 3=方案待确认, 4=服务安排中, 5=服务中, 6=已完成, 7=已取消）',
  `sub_status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'normal' COMMENT '子状态（normal/hold/urgent/reassign/refund_review/refund_done/interrupted）',
  `close_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关闭原因',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_session_code` (`session_code`),
  KEY `idx_equity_code` (`equity_code`),
  KEY `idx_client_code` (`client_code`),
  KEY `idx_butler_code` (`butler_code`),
  KEY `idx_service_type` (`service_type`),
  KEY `idx_park_code` (`park_code`),
  KEY `idx_session_status` (`session_status`),
  KEY `idx_sub_status` (`sub_status`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_quota_reset` (`quota_type`,`quota_reset_year`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='服务会话';
