--
-- Table structure for table `system_dict_iplocation`
--

DROP TABLE IF EXISTS `system_dict_iplocation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `system_dict_iplocation` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ip_start` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'IP起始地址',
  `ip_end` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'IP结束地址',
  `ip_start_num` bigint NOT NULL COMMENT 'IP起始数值（用于快速查询）',
  `ip_end_num` bigint NOT NULL COMMENT 'IP结束数值',
  `country` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '国家',
  `province` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '省份',
  `city` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '城市',
  `district` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '区/县',
  `isp` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '运营商',
  `region_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联区划代码',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  KEY `idx_ip_start_num` (`ip_start_num`),
  KEY `idx_ip_end_num` (`ip_end_num`),
  KEY `idx_region_code` (`region_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统IP地址地域字典';
/*!40101 SET character_set_client = @saved_cs_client */;

