--
-- Table structure for table `system_dict_region`
--

DROP TABLE IF EXISTS `system_dict_region`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `system_dict_region` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `region_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '行政区划代码（国标）',
  `region_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '区划名称',
  `parent_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '父级区划代码',
  `level` tinyint NOT NULL COMMENT '层级（1=省, 2=市, 3=区/县）',
  `pinyin` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '拼音（用于搜索排序）',
  `first_letter` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首字母',
  `lng` decimal(10,6) DEFAULT NULL COMMENT '经度',
  `lat` decimal(10,6) DEFAULT NULL COMMENT '纬度',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序号',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态（0=禁用, 1=启用）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_region_code` (`region_code`),
  KEY `idx_parent_code` (`parent_code`),
  KEY `idx_level` (`level`),
  KEY `idx_first_letter` (`first_letter`)
) ENGINE=InnoDB AUTO_INCREMENT=6709 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统地域字典';
/*!40101 SET character_set_client = @saved_cs_client */;

