--
-- Table structure for table `system_message`
--

DROP TABLE IF EXISTS `system_message`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `system_message` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `message_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息实例编码（全局唯一）',
  `batch_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发送批次编码',
  `template_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联 system_message_template.template_code',
  `biz_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型（与模板 biz_type 对应）',
  `channel_type` tinyint NOT NULL COMMENT '实际发送渠道（1=短信, 2=站内信, 3=APP推送, 4=企微, 5=微信模板, 6=邮件）',
  `message_type` tinyint NOT NULL COMMENT '消息类型（1=系统通知, 2=业务提醒, 3=活动通知, 4=权益通知, 5=服务通知）',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '消息标题（渲染后）',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息正文（模板渲染 + 变量替换后的最终内容）',
  `target_type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '接收者类型（organ/butler/supplier/channel/agent/client）',
  `target_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '接收者编码',
  `target_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '接收者名称（冗余）',
  `target_contact` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '接收者联系方式（手机号/openid/邮箱）',
  `sender_type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system' COMMENT '发送者类型（system/organ/butler/channel）',
  `sender_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发送者编码',
  `link_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '跳转链接（渲染后）',
