--
-- Table structure for table `system_service_change_log`
--

DROP TABLE IF EXISTS `system_service_change_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `system_service_change_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `session_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务会话编码',
  `change_type` tinyint NOT NULL COMMENT '变更类型（1=状态变更, 2=管家变更, 3=方案变更, 4=安排变更, 5=时间变更）',
  `from_value` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '变更前值',
  `to_value` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '变更后值',
  `change_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '变更原因',
  `operator_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作人编码',
  `operator_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作人姓名',
  `operator_type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作人类型（butler/client/system/admin）',
  `operate_time` datetime NOT NULL COMMENT '操作时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  KEY `idx_session_code` (`session_code`),
  KEY `idx_change_type` (`change_type`),
  KEY `idx_operate_time` (`operate_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='服务变更日志';
/*!40101 SET character_set_client = @saved_cs_client */;

