--
-- Table structure for table `system_state_machine`
--

DROP TABLE IF EXISTS `system_state_machine`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `system_state_machine` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `machine_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '状态机编码（如 ORDER_SM、EQUITY_SM、SERVICE_SESSION_SM）',
  `machine_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '状态机名称',
  `biz_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型（order、equity、service等）',
  `from_state` tinyint NOT NULL COMMENT '源主状态值',
  `from_state_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '源主状态名称',
  `from_sub_state` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '源子状态值（单维状态机留空）',
  `to_state` tinyint NOT NULL COMMENT '目标主状态值',
  `to_state_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '目标主状态名称',
  `to_sub_state` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '目标子状态值（单维状态机留空）',
  `event_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '触发事件编码',
  `event_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '触发事件名称',
  `condition_expr` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流转条件表达式',
  `action_bean` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流转执行器（后端类名）',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序号',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态（0=禁用, 1=启用）',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：1已删除/0未删除',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_machine_from_event` (`machine_code`,`from_state`,`from_sub_state`,`event_code`),
  KEY `idx_biz_type` (`biz_type`)
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='状态机';
/*!40101 SET character_set_client = @saved_cs_client */;

